import { execFileSync } from 'node:child_process';
import { promises as fs } from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { afterEach, beforeEach, expect, it, vi } from 'vitest';
import { readCheckPolicy } from '../../../domains/comet-classic/classic-check-policy.js';
import { runClassicCli } from '../../../domains/comet-classic/classic-cli.js';
import { prepareClassicLegacyProject } from '../../helpers/classic-project.js';

// Retain public timeout behavior for persisted v1 managed-check Runs; v2 uses Agent reports.
vi.mock('../../../domains/comet-classic/classic-sdk-application.js', async (importOriginal) => {
  const actual =
    await importOriginal<
      typeof import('../../../domains/comet-classic/classic-sdk-application.js')
    >();
  return {
    ...actual,
    defineClassicAgentWorkflowApplication: actual.defineClassicWorkflowApplication,
  };
});

let root: string;
const identity = { argv: [process.execPath, 'check.cjs'], cwd: '.' };
beforeEach(async () => {
  root = await fs.mkdtemp(path.join(os.tmpdir(), 'classic-check-defaults-'));
  await prepareClassicLegacyProject(root);
  execFileSync('git', ['init', '-b', 'main'], { cwd: root, stdio: 'ignore' });
});
afterEach(async () => {
  await fs.rm(root, { recursive: true, force: true, maxRetries: 5 });
});
async function put(ref: string, text: string) {
  await fs.mkdir(path.dirname(path.join(root, ref)), { recursive: true });
  await fs.writeFile(path.join(root, ref), text);
}
async function invoke(...args: string[]) {
  const separator = args.indexOf('--');
  args.splice(separator < 0 ? args.length : separator, 0, '--json');
  const result = await runClassicCli(args, undefined, { invocationCwd: root });
  return { ...result, response: JSON.parse(result.stdout ?? '{}') };
}
async function cli(...args: string[]) {
  const result = await invoke(...args);
  expect(result.exitCode, result.stdout ?? result.stderr).toBe(0);
  return result.response.data;
}
async function prepare(runtime: 'compat' | 'sdk') {
  await cli('state', 'init', 'demo', 'tweak', '--runtime', runtime, '--isolation', 'current');
  await put('openspec/changes/demo/proposal.md', '# Proposal\nFix source.\n');
  await put('openspec/changes/demo/design.md', '# Design\nKeep public behavior.\n');
  await put('openspec/changes/demo/tasks.md', '- [x] Fix source <!-- comet-task:source -->\n');
  const open = await cli('guard', 'demo', 'open');
  await cli(
    'guard',
    'demo',
    'open',
    '--apply',
    ...(runtime === 'sdk' ? ['--approval-hash', open.approvalHash] : []),
  );
  if (runtime === 'sdk') await cli('state', 'complete-build', 'demo');
}
const policy = (command: Record<string, unknown>) =>
  put(
    '.comet/check-policy.json',
    JSON.stringify({ version: 2, commands: [{ ...identity, ...command }] }),
  );

it.each(['compat', 'sdk'] as const)(
  'applies project timeout to the public %s check run',
  async (runtime) => {
    await prepare(runtime);
    await fs.appendFile(path.join(root, '.comet/config.yaml'), '  check_timeout_ms: 25\n');
    const result = await invoke(
      'check',
      'run',
      'demo',
      'build',
      '--',
      process.execPath,
      '-e',
      // 保持命令存活到超时终止，避免它在 Windows taskkill 枚举期间自然退出。
      'setTimeout(() => {}, 20000)',
    );
    expect(result.exitCode, result.stdout).toBe(124);
    expect(result.response.data.timeoutMs).toBe(25);
  },
);

it.each(['compat', 'sdk'] as const)(
  'lets explicit CLI timeout override the project default for %s',
  async (runtime) => {
    await prepare(runtime);
    await fs.appendFile(path.join(root, '.comet/config.yaml'), '  check_timeout_ms: 1\n');
    const result = await invoke(
      'check',
      'run',
      'demo',
      'build',
      '--timeout-ms',
      '5000',
      '--',
      process.execPath,
      '-e',
      'setTimeout(() => {}, 50)',
    );
    expect(result.exitCode, result.stdout).toBe(0);
    expect(result.response.data.timeoutMs).toBe(5000);
  },
);

it.each([{ presets: ['unknown'] }, { presets: 'vite' }, { presets: [false] }])(
  'rejects invalid presets %j',
  async ({ presets }) => {
    await policy({ presets });
    await expect(readCheckPolicy(root, identity)).rejects.toThrow(/preset/iu);
  },
);

it('does not reuse a command executed under a different explicit timeout', async () => {
  await prepare('compat');
  const argv = [process.execPath, '-e', 'setTimeout(() => {}, 50)'];
  const first = await cli(
    'check',
    'run',
    'demo',
    'build',
    '--local',
    '--timeout-ms',
    '5000',
    '--',
    ...argv,
  );
  expect(first.exitCode).toBe(0);
  const second = await invoke(
    'check',
    'run',
    'demo',
    'build',
    '--local',
    '--timeout-ms',
    '1',
    '--',
    ...argv,
  );
  expect(second.exitCode, second.stdout).toBe(124);
  expect(second.response.data.timeoutMs).toBe(1);
  expect(second.response.data.reused).not.toBe(true);
});

it('rerun preserves the previous resolved timeout rather than a changed project default', async () => {
  await prepare('compat');
  const configPath = path.join(root, '.comet/config.yaml');
  const initialConfig = await fs.readFile(configPath, 'utf8');
  await fs.writeFile(configPath, initialConfig + '  check_timeout_ms: 5000\n');
  const first = await cli(
    'check',
    'run',
    'demo',
    'build',
    '--',
    process.execPath,
    '-e',
    'setTimeout(() => {}, 50)',
  );
  expect(first.timeoutMs).toBe(5000);
  await fs.writeFile(configPath, initialConfig + '  check_timeout_ms: 1\n');
  const rerun = await cli('check', 'rerun', 'demo', 'build');
  expect(rerun.timeoutMs).toBe(5000);
});

import { resolveClassicRunDirectory } from '../../../domains/comet-classic/classic-runtime-paths.js';
import { promises as fs } from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { afterEach, beforeEach, expect, it, vi } from 'vitest';
import * as store from '../../../domains/comet-classic/classic-run-store.js';
import { readCheckIndex } from '../../../domains/comet-classic/classic-check-index.js';

let root: string;
const ref = '.comet/trajectory.jsonl';
beforeEach(async () => {
  root = await fs.mkdtemp(path.join(os.tmpdir(), 'classic-index-'));
  await fs.mkdir(path.join(root, '.git'));
  await fs.writeFile(
    path.join(root, '.comet.yaml'),
    'change_id: 00000000-0000-0000-0000-000000000001\n',
  );
});
afterEach(async () => {
  vi.restoreAllMocks();
  await fs.rm(root, { recursive: true, force: true, maxRetries: 5 });
});
const append = (sequence: number) =>
  store.appendTrajectory(root, ref, {
    sequence,
    timestamp: '',
    runId: 'run',
    type: 'command_check_started',
    data: { scope: 'verify' },
  });
it('reuses an unchanged protected trajectory and rebuilds after external writes', async () => {
  await append(1);
  const read = vi.spyOn(store, 'readTrajectory');
  expect((await readCheckIndex(root, ref)).maximumSequence).toBe(1);
  expect((await readCheckIndex(root, ref)).maximumSequence).toBe(1);
  expect(read).toHaveBeenCalledTimes(1);
  await append(2);
  expect((await readCheckIndex(root, ref)).maximumSequence).toBe(2);
  expect(read).toHaveBeenCalledTimes(2);
});
it('does not trust forged disk indexes, mutable returned values or damaged logs', async () => {
  await append(1);
  await fs.writeFile(
    path.join(await resolveClassicRunDirectory(root), '.comet/check-index.json'),
    '{"maximumSequence":999}',
  );
  const index = await readCheckIndex(root, ref);
  index.maximumSequence = 999;
  index.events.length = 0;
  expect((await readCheckIndex(root, ref)).maximumSequence).toBe(1);
  await fs.writeFile(path.join(await resolveClassicRunDirectory(root), ref), 'corrupt\n');
  await expect(readCheckIndex(root, ref)).rejects.toThrow(/Trajectory/i);
});
it('rejects paths outside the change directory', async () => {
  await expect(readCheckIndex(root, '../trajectory.jsonl')).rejects.toThrow();
});

it('rejects a junction ancestor instead of reusing cached success', async () => {
  await append(1);
  await readCheckIndex(root, ref);
  const original = path.join(await resolveClassicRunDirectory(root), '.comet');
  const moved = path.join(root, 'moved');
  await fs.rename(original, moved);
  await fs.symlink(moved, original, 'junction');
  await expect(readCheckIndex(root, ref)).rejects.toThrow(/symbolic|junction/i);
});

it('rebuilds a replaced trajectory even when length and mtime are preserved', async () => {
  await append(1);
  await readCheckIndex(root, ref);
  const file = path.join(await resolveClassicRunDirectory(root), ref);
  const stat = await fs.stat(file);
  const raw = await fs.readFile(file, 'utf8');
  await fs.writeFile(file, raw.replace('"sequence":1', '"sequence":2'));
  await fs.utimes(file, stat.atime, stat.mtime);
  expect((await readCheckIndex(root, ref)).maximumSequence).toBe(2);
});

import { describe, expect, it } from 'vitest';
import {
  checkManifestHash,
  compileCheckPolicyInputPattern,
  compileCheckPolicyPattern,
  diffCheckManifests,
  hasGlobCharacters,
  parseCheckManifest,
  serializeCheckManifest,
} from '../../../domains/comet-classic/classic-check-manifest.js';

describe('Classic check manifests', () => {
  it('round-trips entries through a deterministic serialization', () => {
    const entries = [
      { p: 'src/b.ts', h: 'b'.repeat(64), s: 2, m: '200' },
      { p: 'src/a.ts', h: 'a'.repeat(64), s: 1, m: '100' },
      { p: '\u0000git:.:head', h: 'c'.repeat(64), s: null, m: null },
    ];
    const serialized = serializeCheckManifest(entries);
    expect(serialized.split('\n')).toHaveLength(3);
    expect(checkManifestHash(serialized)).toMatch(/^[a-f0-9]{64}$/);
    expect(parseCheckManifest(serialized)).toEqual(
      entries.slice().sort((a, b) => (a.p < b.p ? -1 : a.p > b.p ? 1 : 0)),
    );
  });

  it('rejects malformed manifest lines', () => {
    expect(() => parseCheckManifest('{"p":"a.ts"}')).toThrow(/manifest/i);
    expect(() => parseCheckManifest('not json')).toThrow();
    expect(parseCheckManifest('')).toEqual([]);
  });

  it('detects glob characters', () => {
    expect(hasGlobCharacters('src/**')).toBe(true);
    expect(hasGlobCharacters('src/a?b.ts')).toBe(true);
    expect(hasGlobCharacters('src/plain.ts')).toBe(false);
  });

  it.each([
    ['src', 'src/obsolete.js', true],
    ['src', 'src/nested/obsolete.js', true],
    ['src', 'src-other/obsolete.js', false],
    ['src', 'src.js', false],
    ['source.js', 'source.js', true],
    ['source.js', 'source.js.bak', false],
    ['src/*.js', 'src/obsolete.js', true],
    ['src/*.js', 'src/nested/obsolete.js', false],
  ])('matches input %s against %s as %s', (pattern, relative, expected) => {
    expect(compileCheckPolicyInputPattern(pattern)(relative)).toBe(expected);
  });

  it('does not apply input directory semantics to output patterns', () => {
    expect(compileCheckPolicyPattern('src')('src/obsolete.js')).toBe(false);
  });

  it.each([
    ['src/**', 'src/a.ts', true],
    ['src/**', 'src/nested/deep/b.ts', true],
    ['src/**', 'lib/a.ts', false],
    ['**/generated/**', 'src/generated/out.json', true],
    ['**/generated/**', 'generated/out.json', true],
    ['*.ts', 'a.ts', true],
    ['*.ts', 'src/a.ts', false],
    ['src/*.test.ts', 'src/a.test.ts', true],
    ['src/*.test.ts', 'src/nested/a.test.ts', false],
    ['src/a?c.ts', 'src/abc.ts', true],
    ['src/a?c.ts', 'src/a/c.ts', false],
    ['package.json', 'package.json', true],
    ['package.json', 'package.json.bak', false],
  ])('matches %s against %s as %s', (pattern, relative, expected) => {
    expect(compileCheckPolicyPattern(pattern)(relative)).toBe(expected);
  });
});

import { promises as fs } from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { afterEach, beforeEach, expect, it, vi } from 'vitest';
import { readCheckPolicy } from '../../../domains/comet-classic/classic-check-policy.js';
import { prepareClassicLegacyProject } from '../../helpers/classic-project.js';

let root: string;
let change: string;
const identity = { argv: [process.execPath, 'check.cjs'], cwd: '.' };
beforeEach(async () => {
  root = await fs.mkdtemp(path.join(os.tmpdir(), 'classic-policy-'));
  await prepareClassicLegacyProject(root);
  change = path.join(root, 'openspec/changes/demo');
  await fs.mkdir(change, { recursive: true });
  await fs.writeFile(path.join(root, 'input.txt'), 'input');
});
afterEach(async () => {
  vi.unstubAllEnvs();
  await fs.rm(root, { recursive: true, force: true, maxRetries: 5 });
});
const writePolicy = (value: Record<string, unknown>) =>
  fs.writeFile(
    path.join(root, '.comet/check-policy.json'),
    JSON.stringify({ ...identity, ...value }),
  );

it.each([
  { version: 2 },
  { version: 1, files: ['../outside'] },
  { version: 1, files: ['*.ts'] },
  { version: 1, env: 'PATH' },
  { version: 1, git: false },
  { version: 1, typo: true },
  { version: 1, argv: undefined },
  { version: 1, cwd: undefined },
])('rejects invalid policy %j without relaxing defaults', async (policy) => {
  await writePolicy(policy);
  await expect(readCheckPolicy(root, identity)).rejects.toThrow(/policy/i);
});

it.each([
  { argv: ['security-scan'], cwd: '.' },
  { argv: identity.argv, cwd: 'package' },
])('keeps unmatched command identity %j on the default bindings', async (other) => {
  await writePolicy({
    version: 1,
    files: ['input.txt'],
    env: [],
    git: 'all',
    taskCheckboxes: 'include',
  });
  expect(await readCheckPolicy(root, other)).toMatchObject({
    git: 'none',
    taskCheckboxes: 'ignore',
  });
  expect((await readCheckPolicy(root, other)).env).toBeUndefined();
});

const writeRawPolicy = (value: unknown) =>
  fs.writeFile(path.join(root, '.comet/check-policy.json'), JSON.stringify(value));

const v2Commands = (
  first: Record<string, unknown> = {},
  secondFiles: string[] = ['other.txt'],
) => ({
  version: 2,
  commands: [
    { argv: identity.argv, cwd: '.', files: ['input.txt', 'src/**'], git: 'all', ...first },
    { argv: ['node', 'other.mjs'], cwd: '.', files: secondFiles },
  ],
});

it('resolves the matching v2 command entry', async () => {
  await writeRawPolicy(v2Commands());
  const policy = await readCheckPolicy(root, identity);
  expect(policy).toMatchObject({ git: 'all', files: ['input.txt', 'src/**'] });
  const other = { argv: ['node', 'other.mjs'], cwd: '.' };
  const otherPolicy = await readCheckPolicy(root, other);
  expect(otherPolicy).toMatchObject({ files: ['other.txt'], git: 'none' });
  const unmatched = await readCheckPolicy(root, { argv: ['nope'], cwd: '.' });
  expect(unmatched).toMatchObject({ git: 'none', taskCheckboxes: 'ignore' });
});

it('keeps the selected policy unchanged when another command declaration changes', async () => {
  await writeRawPolicy(v2Commands());
  const first = await readCheckPolicy(root, identity);
  await writeRawPolicy(v2Commands({}, ['other.txt', 'extra.txt']));
  expect(await readCheckPolicy(root, identity)).toMatchObject({
    files: first.files,
    git: first.git,
    declaredCwd: first.declaredCwd,
  });
});

it.each([
  { version: 2, commands: [], note: 'empty' },
  { version: 2, commands: [{ argv: ['node', 'a.mjs'] }], note: 'missing cwd' },
  { version: 2, commands: [{ argv: ['x'], cwd: '.', typo: 1 }], note: 'unknown field' },
  {
    version: 2,
    commands: [
      { argv: ['node', 'a.mjs'], cwd: '.' },
      { argv: ['node', 'a.mjs'], cwd: '.' },
    ],
    note: 'duplicate identity',
  },
  { version: 2, commands: [{ argv: ['x'], cwd: '.', files: ['../outside'] }], note: 'unsafe' },
  { version: 2, extra: true, commands: [{ argv: ['x'], cwd: '.' }], note: 'unknown top level' },
])('rejects invalid v2 policy (%s)', async (policy) => {
  await writeRawPolicy(policy);
  await expect(readCheckPolicy(root, identity)).rejects.toThrow(/policy/i);
});

import { promises as fs } from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { afterEach, expect, it } from 'vitest';
import {
  createRuntime,
  createMemoryRuntimeStore,
  createFileRuntimeStore,
  createPortableRunCheckpoint,
  hashRuntimeValue,
  preserveRuntimeExecutionOrigins,
  type WorkflowRun,
} from '../../../domains/engine/runtime.js';
import {
  assertClassicSdkCheckReceipt,
  recordClassicSdkCheckReceipt,
  classicSdkCheckRecordRef,
} from '../../../domains/comet-classic/classic-sdk-check-record.js';
import { resolveWorkspaceRuntimeRoot } from '../../../domains/workflow-contract/workspace-runtime.js';
const roots: string[] = [];
afterEach(async () => {
  await Promise.all(roots.splice(0).map((root) => fs.rm(root, { recursive: true, force: true })));
});
async function fixture() {
  const root = await fs.mkdtemp(path.join(os.tmpdir(), 'classic-origin-'));
  roots.push(root);
  const runtime = createRuntime({
    store: createMemoryRuntimeStore<WorkflowRun>(),
    workflows: [
      {
        id: 'classic-origin',
        version: '1',
        entry: 'check',
        steps: { check: { type: 'call_tool', ref: 'classic-check' } },
      },
    ],
  });
  const run = await runtime.start({
    runId: 'example',
    workflow: { id: 'classic-origin', version: '1' },
    input: { changeDir: 'openspec/changes/example' },
  });
  const action = run.actions[0];
  return {
    root,
    run: await runtime.claim({
      runId: run.runId,
      actionId: action.id,
      attempt: action.attempt,
      inputHash: action.inputHash,
      executorId: 'comet-classic-check',
      claimToken: 'original-execution',
    }),
  };
}
const result = { status: 'succeeded' as const, output: { exitCode: 0 } };
it('retains the same receipt and recovery record identity across portable restore and approved definition changes', async () => {
  const { root, run } = await fixture();
  await recordClassicSdkCheckReceipt(root, run, run.actions[0], result);
  const next = preserveRuntimeExecutionOrigins(createPortableRunCheckpoint(run).run);
  next.workflow.hash = 'b'.repeat(64);
  expect(classicSdkCheckRecordRef(next, next.actions[0])).toBe(
    classicSdkCheckRecordRef(run, run.actions[0]),
  );
  await expect(
    assertClassicSdkCheckReceipt(root, next, next.actions[0], result),
  ).resolves.toBeUndefined();
  const forged = structuredClone(next);
  forged.actions[0].claim!.token = 'different-execution';
  await expect(
    assertClassicSdkCheckReceipt(root, forged, forged.actions[0], result),
  ).rejects.toThrow('original Runtime execution receipt');
});
it('accepts an exact legacy raw-key receipt and rejects a conflicting alias', async () => {
  const { root, run } = await fixture();
  const action = run.actions[0];
  const id = hashRuntimeValue({
    workflow: run.workflow,
    runId: run.runId,
    actionId: action.id,
    attempt: action.attempt,
    inputHash: action.inputHash,
    claim: action.claim,
  });
  const store = createFileRuntimeStore<{
    runId: string;
    revision: number;
    schema: string;
    result: unknown;
    resultHash: string;
  }>({
    rootDir: path.join(await resolveWorkspaceRuntimeRoot(root), 'check-receipts/classic'),
  });
  await store.compareAndSwap(id, null, {
    runId: id,
    revision: 1,
    schema: 'comet.classic-sdk-check-receipt.v1',
    result,
    resultHash: hashRuntimeValue(result),
  });
  await expect(assertClassicSdkCheckReceipt(root, run, action, result)).resolves.toBeUndefined();
  await expect(
    recordClassicSdkCheckReceipt(root, run, action, {
      status: 'failed',
      output: { exitCode: 1 },
    }),
  ).rejects.toThrow('original Runtime execution receipt');
  const stable = hashRuntimeValue(
    (await import('../../../domains/engine/runtime.js')).runtimeExecutionBinding(run, action),
  );
  const conflicting = { status: 'failed', output: { exitCode: 1 } };
  await store.compareAndSwap(stable, null, {
    runId: stable,
    revision: 1,
    schema: 'comet.classic-sdk-check-receipt.v1',
    result: conflicting,
    resultHash: hashRuntimeValue(conflicting),
  });
  await expect(assertClassicSdkCheckReceipt(root, run, action, result)).rejects.toThrow(
    'original Runtime execution receipt',
  );
});

import { promises as fs } from 'node:fs';
import { execFile } from 'node:child_process';
import os from 'node:os';
import path from 'node:path';
import { promisify } from 'node:util';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';

import {
  inspectNativeBuildEvidence,
  persistNativeBuildEvidence,
  prepareNativeBuildEvidence,
} from '../../../domains/comet-native/native-build-evidence.js';
import { executeNativeCheckReceipt } from '../../../domains/comet-native/native-check-receipt.js';
import {
  createNativeChange,
  nativeChangeDir,
  writeNativeChange,
} from '../../../domains/comet-native/native-change.js';
import {
  readNativeImplementationScope,
  readNativeImplementationScopeBundle,
} from '../../../domains/comet-native/native-evidence-storage.js';
import { nativeProjectPaths } from '../../../domains/comet-native/native-paths.js';
import type {
  NativeChangeState,
  NativeContentSnapshotManifest,
  NativeProjectPaths,
} from '../../../domains/comet-native/native-types.js';

const execFileAsync = promisify(execFile);
const snapshotMock = vi.hoisted(() => ({
  next: null as NativeContentSnapshotManifest | null,
  filtered: null as NativeContentSnapshotManifest | null,
}));

vi.mock('../../../domains/comet-native/native-snapshot.js', async (importOriginal) => {
  const actual =
    await importOriginal<typeof import('../../../domains/comet-native/native-snapshot.js')>();
  return {
    ...actual,
    createNativeCurrentContentSnapshot: async (
      ...args: Parameters<typeof actual.createNativeCurrentContentSnapshot>
    ) => {
      if (snapshotMock.next !== null) {
        const next = snapshotMock.next;
        snapshotMock.next = null;
        return next;
      }
      return actual.createNativeCurrentContentSnapshot(...args);
    },
    filterNativeContentSnapshotToProjectScope: async (
      ...args: Parameters<typeof actual.filterNativeContentSnapshotToProjectScope>
    ) => {
      if (snapshotMock.filtered !== null) {
        const filtered = snapshotMock.filtered;
        snapshotMock.filtered = null;
        return filtered;
      }
      return actual.filterNativeContentSnapshotToProjectScope(...args);
    },
  };
});

const brief = `# Outcome
Ship the focused behavior.
# Scope
Update the declared implementation.
# Non-goals
No unrelated refactor.
# Acceptance examples
- The focused behavior works.
# Constraints and invariants
Keep existing callers stable.
# Decisions
Use the existing module.
# Open questions
None.
# Verification expectations
Run the focused tests.
`;

function changedGitSelectionSnapshot(
  origin: NativeContentSnapshotManifest['origin'] = 'explicit',
): NativeContentSnapshotManifest {
  return {
    schema: 'comet.native.content-snapshot.v1',
    origin,
    capture: {
      provider: 'git',
      gitSelection: {
        schema: 'comet.native.git-selection.v1',
        status: 'changed',
        stageBefore: {
          hash: 'a'.repeat(64),
          recordCount: 1,
          storedRecordCount: 1,
          stdoutBytes: 80,
          overflow: false,
        },
        combined: {
          hash: 'b'.repeat(64),
          recordCount: 1,
