} from '../../../domains/comet-native/native-check-executor.js';

describe('Native check executor', () => {
  let root: string;
  let runtimeDir: string;

  beforeEach(async () => {
    root = await fs.mkdtemp(path.join(os.tmpdir(), 'comet-native-check-'));
    runtimeDir = path.join(root, '.comet', 'runtime', 'native', 'changes', 'example');
    await fs.mkdir(runtimeDir, { recursive: true });
  });

  afterEach(async () => {
    vi.unstubAllEnvs();
    // Windows 进程退出后可能短暂占用 cwd；有限重试，不掩盖持续占用。
    await fs.rm(root, { recursive: true, force: true, maxRetries: 5, retryDelay: 100 });
  });

  it('streams output longer than 64 KiB to a log without summary validation', async () => {
    const result = await executeNativeCheck({
      projectRoot: root,
      runtimeDir,
      operationId: 'verify-1',
      plan: {
        id: 'long-output',
        name: 'Long output',
        executable: process.execPath,
        argv: ['-e', "process.stdout.write('x'.repeat(256 * 1024))"],
        cwdRef: '.',
        timeoutMs: 10_000,
        repeatable: true,
      },
    });

    expect(result.status).toBe('passed');
    expect((await fs.stat(path.join(runtimeDir, ...result.logRef.split('/')))).size).toBe(
      256 * 1024,
    );
    expect(result).not.toHaveProperty('outputSummary');
  });

  it('derives failed and interrupted states from exit and timeout', async () => {
    const failed = await executeNativeCheck({
      projectRoot: root,
      runtimeDir,
      operationId: 'verify-2',
      plan: {
        id: 'failure',
        name: 'Failure',
        executable: process.execPath,
        argv: ['-e', 'process.exit(7)'],
        cwdRef: '.',
        timeoutMs: 10_000,
        repeatable: true,
      },
    });
    const timedOut = await executeNativeCheck({
      projectRoot: root,
      runtimeDir,
      operationId: 'verify-3',
      plan: {
        id: 'timeout',
        name: 'Timeout',
        executable: process.execPath,
        argv: ['-e', 'setInterval(() => {}, 1000)'],
        cwdRef: '.',
        timeoutMs: 5_000,
        repeatable: true,
      },
    });

    expect(failed).toMatchObject({ status: 'failed', exitCode: 7, timedOut: false });
    expect(timedOut).toMatchObject({ status: 'interrupted', timedOut: true });
  });

  it.runIf(process.platform === 'win32')(
    'resolves Windows command shims without a shell',
    async () => {
      await fs.writeFile(
        path.join(root, 'comet-check-shim.cmd'),
        `@"${process.execPath}" "%~dp0shim.cjs" %*\r\n`,
      );
      await fs.writeFile(
        path.join(root, 'shim.cjs'),
        'process.stdout.write(JSON.stringify(process.argv.slice(2)))',
      );
      vi.stubEnv('PATH', `${root}${path.delimiter}${process.env.PATH ?? ''}`);
      const result = await executeNativeCheck({
        projectRoot: root,
        runtimeDir,
        operationId: 'verify-shim',
        plan: {
          id: 'local-shim',
          name: 'Local Windows command shim',
          executable: 'comet-check-shim',
          argv: ['space separated', '中文'],
          cwdRef: '.',
          timeoutMs: 10_000,
          repeatable: true,
        },
      });

      const output = await fs.readFile(path.join(runtimeDir, ...result.logRef.split('/')), 'utf8');
      expect(result, JSON.stringify({ result, output })).toMatchObject({
        status: 'passed',
        exitCode: 0,
        timedOut: false,
      });
      expect(output).toBe(JSON.stringify(['space separated', '中文']));
    },
  );

  it('terminates the complete child process tree after timeout', async () => {
    const marker = path.join(root, 'grandchild-heartbeat.txt');
    const grandchild =
      "const fs=require('node:fs');const beat=()=>fs.appendFileSync(process.argv[1], 'x');beat();setInterval(beat,25)";
    const parent = `require('node:child_process').spawn(process.execPath, ['-e', ${JSON.stringify(grandchild)}, process.argv[1]], { stdio: 'ignore', windowsHide: true }); setInterval(() => {}, 1000)`;
    const result = await executeNativeCheck({
      projectRoot: root,
      runtimeDir,
      operationId: 'verify-tree-timeout',
      plan: {
        id: 'tree-timeout',
        name: 'Tree timeout',
        executable: process.execPath,
        argv: ['-e', parent, marker],
        cwdRef: '.',
        timeoutMs: 5_000,
        repeatable: true,
      },
    });
    expect(result).toMatchObject({ status: 'interrupted', timedOut: true });
    // 先证明孙进程实际运行，再核对监管进程返回后已停止写入。
    const heartbeat = await fs.readFile(marker, 'utf8');
    expect(heartbeat.length).toBeGreaterThan(0);
    await new Promise((resolve) => setTimeout(resolve, 500));
    expect(await fs.readFile(marker, 'utf8')).toBe(heartbeat);
  });

  it('keeps cwd inside the project and redacts portable argv displays', () => {
    expect(resolveNativeCheckCwd(root, '.')).toBe(root);
    expect(() => resolveNativeCheckCwd(root, '../outside')).toThrow('project-relative');
    expect(nativePortableArgvDisplay(['--token=secret-value'])).not.toContain('secret-value');
    expect(
      nativePortableArgvDisplay([
        '--token',
        'token-value',
        '--client-secret',
        'client-value',
        '-p',
        'password-value',
        '--safe',
        'visible-value',
      ]),
    ).toEqual([
      '--token',
      '[REDACTED]',
      '--client-secret',
      '[REDACTED]',
      '-p',
      '[REDACTED]',
      '--safe',
      'visible-value',
    ]);
  });

  it('requires explicit generated output paths and rejects broad or unsafe exclusions', () => {
    expect(normalizeNativeCheckOutputs(['dist/eval', 'dist/eval'])).toEqual(['dist/eval']);
    for (const ref of [
      'dist',
      '.',
      '../dist/eval',
      '/dist/eval',
      'C:/dist/eval',
      'dist/eval/**',
      'src/code.ts',
      'dist/.comet/state',
      'dist\\eval',
    ])
      expect(() => normalizeNativeCheckOutputs([ref]), ref).toThrow(/outputs/u);
  });

  it('rejects a missing check working directory during preflight', () => {
    expect(() =>
      preflightNativeCheckPlans(root, [
        {
          id: 'missing-cwd',
          name: 'Missing working directory',
          executable: process.execPath,
          argv: ['-e', 'process.exit(0)'],
          cwdRef: 'missing-working-directory',
          timeoutMs: 1_000,
          repeatable: true,
        },
      ]),
    ).toThrow(/working directory|cwd|directory|exist/iu);
  });
});

import { spawn, type ChildProcess } from 'node:child_process';
import { promises as fs } from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { build } from 'esbuild';
import { afterEach, describe, expect, it } from 'vitest';

import { executeNativeCheck } from '../../../domains/comet-native/native-check-executor.js';
import {
  createNativeSdkCheckExecution as createCheckExecution,
  inspectNativeSdkCheckExecutions,
  terminateNativeSdkCheckExecutions,
} from '../../../domains/comet-native/native-sdk-check-execution.js';
import { recoverNativeSdkChecks } from '../../../domains/comet-native/native-sdk-checks.js';
import { createRuntime, createMemoryRuntimeStore } from '../../../domains/engine/runtime.js';
import {
  inspectProcessTreeLiveness,
  readProcessIdentity,
} from '../../../platform/process/process-identity.js';
import { spawnOwnedCommand } from '../../../platform/process/owned-command.js';
import { waitForCondition, waitForProcessExit } from '../../helpers/native-portable-process.js';

const openExecutions: Array<Awaited<ReturnType<typeof createCheckExecution>>> = [];
async function createNativeSdkCheckExecution(options: Parameters<typeof createCheckExecution>[0]) {
  const execution = await createCheckExecution(options);
  openExecutions.push(execution);
  return execution;
}

const roots: string[] = [];
const processes: ChildProcess[] = [];
afterEach(async () => {
  await Promise.all(openExecutions.splice(0).map((execution) => execution.release()));
  for (const child of processes.splice(0)) {
    try {
      process.kill(-child.pid!, 'SIGKILL');
    } catch {
      child.kill('SIGKILL');
    }
    await waitForProcessExit(child).catch(() => {});
  }
  for (const root of roots.splice(0)) await fs.rm(root, { recursive: true, force: true });
});
async function root() {
  const value = await fs.mkdtemp(path.join(os.tmpdir(), 'comet-check-owner-'));
  roots.push(value);
  return value;
}
const exists = async (file: string) =>
  fs.access(file).then(
    () => true,
    () => false,
  );
const sleep = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));

async function claimedRun() {
  const runtime = createRuntime({
    store: createMemoryRuntimeStore(),
    workflows: [
      {
        id: 'check-owner',
        version: '1',
        entry: 'verify.checks',
        steps: {
          'verify.checks': { type: 'call_tool', ref: 'native-required-checks', retry: 'reconcile' },
        },
      },
    ],
  });
  let run = await runtime.start({
    runId: 'owner-test',
    workflow: { id: 'check-owner', version: '1' },
    input: {},
  });
  const pending = run.actions[0];
  run = await runtime.claim({
    runId: run.runId,
    actionId: pending.id,
    attempt: pending.attempt,
    inputHash: pending.inputHash,
    executorId: 'comet-native-checks',
    claimToken: 'owner-claim',
  });
  return { runtime, run, action: run.actions[0] };
}

describe('Native check owner recovery', () => {
  it('recognizes completed receipt reuse without a child but keeps an unregistered launch unknown', async () => {
    const directory = await root();
    const { run, action } = await claimedRun();
    const registration = await createNativeSdkCheckExecution({
      projectRoot: directory,
      run,
      action,
      candidateId: 'candidate',
      plansHash: 'plans',
    });
    registration.execution.checks = [
      {
        id: 'once',
        status: 'passed',
        reusedFrom: { actionId: 'original', attempt: 1, candidateId: 'candidate', checkId: 'once' },
      },
    ];
    registration.execution.phase = 'completed';
    await registration.save();
    expect(
      (await inspectNativeSdkCheckExecutions({ projectRoot: directory, run }))[0].quiescent,
    ).toBe(false);
    registration.execution.terminationUnconfirmed = false;
    await registration.save();
    await registration.release();
    expect(
      (await inspectNativeSdkCheckExecutions({ projectRoot: directory, run }))[0].quiescent,
    ).toBe(true);
    registration.execution.checks = [{ id: 'once', status: 'passed' }];
    await registration.save();
    expect(
      (await inspectNativeSdkCheckExecutions({ projectRoot: directory, run }))[0].quiescent,
    ).toBe(false);
  });
  it.each(['SIGTERM', 'SIGKILL'] as const)(
    'stops checks and their descendants when their actual owner receives %s',
    async (signal) => {
      const directory = await root();
      const started = path.join(directory, 'started');
      const marker = path.join(directory, 'late');
      const bundle = path.join(directory, 'owner.cjs');
      const grandchild =
        "setTimeout(() => require('node:fs').writeFileSync(process.argv[1], 'late'), 800); setTimeout(() => process.exit(0), 1300)";
      const command = `require('node:fs').writeFileSync(process.argv[1], String(process.pid)); require('node:child_process').spawn(process.execPath, ['-e', ${JSON.stringify(grandchild)}, process.argv[2]], { stdio: 'ignore' }); setTimeout(() => process.exit(0), 1600)`;
      await build({
        stdin: {
          contents: `const { executeNativeCheck } = require('./domains/comet-native/native-check-executor.ts'); executeNativeCheck({projectRoot:process.env.COMET_TEST_ROOT,runtimeDir:require('node:path').join(process.env.COMET_TEST_ROOT,'runtime'),operationId:'owner',plan:{id:'check',name:'owner',executable:process.execPath,argv:['-e',${JSON.stringify(command)},process.env.COMET_TEST_STARTED,process.env.COMET_TEST_MARKER],cwdRef:'.',timeoutMs:5000,repeatable:false}}).catch(() => process.exitCode = 1);`,
          resolveDir: process.cwd(),
        },
        outfile: bundle,
        bundle: true,
        platform: 'node',
        format: 'cjs',
        logLevel: 'silent',
      });
      const owner = spawn(process.execPath, [bundle], {
        stdio: 'ignore',
        env: {
          ...process.env,
          COMET_TEST_ROOT: directory,
          COMET_TEST_STARTED: started,
          COMET_TEST_MARKER: marker,
        },
      });
      processes.push(owner);
      await waitForCondition(() => exists(started), 'check did not start', 5000);
      owner.kill(signal);
      await waitForProcessExit(owner);
      await sleep(1050);
      expect(await exists(marker)).toBe(false);
    },
  );

  it('keeps its deadline when the owner event loop cannot run its timeout timer', async () => {
    const directory = await root();
    const marker = path.join(directory, 'timer-late');
    const started = path.join(directory, 'timer-started');
    const bundle = path.join(directory, 'blocked-owner.cjs');
    const command =
      "require('node:fs').writeFileSync(process.argv[1], 'started'); setTimeout(() => require('node:fs').writeFileSync(process.argv[2], 'late'), 5500); setTimeout(() => process.exit(0), 8000)";
    await build({
      stdin: {
        contents: `const { executeNativeCheck } = require('./domains/comet-native/native-check-executor.ts'); executeNativeCheck({projectRoot:process.env.COMET_TEST_ROOT,runtimeDir:require('node:path').join(process.env.COMET_TEST_ROOT,'runtime'),operationId:'blocked-owner',plan:{id:'check',name:'blocked owner',executable:process.execPath,argv:['-e',${JSON.stringify(command)},process.env.COMET_TEST_STARTED,process.env.COMET_TEST_MARKER],cwdRef:'.',timeoutMs:5000,repeatable:false}}).catch(() => {}); const poll=setInterval(()=>{if(require('node:fs').existsSync(process.env.COMET_TEST_STARTED)){clearInterval(poll);Atomics.wait(new Int32Array(new SharedArrayBuffer(4)),0,0,6000)}},25);`,
        resolveDir: process.cwd(),
      },
      outfile: bundle,
      bundle: true,
      platform: 'node',
      format: 'cjs',
      logLevel: 'silent',
    });
    const owner = spawn(process.execPath, [bundle], {
      stdio: 'ignore',
      env: {
        ...process.env,
        COMET_TEST_ROOT: directory,
        COMET_TEST_STARTED: started,
        COMET_TEST_MARKER: marker,
      },
    });
    processes.push(owner);
    await waitForCondition(() => exists(started), 'check did not start', 5000);
    await sleep(6500);
    expect(await exists(marker)).toBe(false);
    await waitForProcessExit(owner);
  });

  it('does not launch the command before registration and bounds a stuck registration', async () => {
    const directory = await root();
