import { promises as fs } from 'node:fs';
import { execFileSync } from 'node:child_process';
import os from 'node:os';
import path from 'node:path';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';

import { detectNativeGitExternalDrift } from '../../../domains/comet-native/native-git-provenance.js';
import type { NativeSnapshotProjection } from '../../../domains/comet-native/native-verification-scope.js';

const projection = (entry: { path: string; gitObjectId: string }): NativeSnapshotProjection => ({
  schema: 'comet.native.snapshot-projection.v1',
  origin: 'change-created',
  complete: true,
  limits: {
    maxFiles: 10,
    maxFileBytes: 1024,
    maxTotalBytes: 1024,
    maxDurationMs: 1000,
  },
  entries: [
    {
      path: entry.path,
      hash: 'a'.repeat(64),
      size: 1,
      type: 'file',
      gitObjectId: entry.gitObjectId,
    },
  ],
  omitted: [],
  omittedCount: 0,
});

describe('Native Git provenance', () => {
  let projectRoot: string;

  beforeEach(async () => {
    projectRoot = await fs.mkdtemp(path.join(os.tmpdir(), 'comet-native-provenance-'));
    execFileSync('git', ['init'], { cwd: projectRoot, stdio: 'ignore' });
    execFileSync('git', ['config', 'user.email', 'native@example.test'], { cwd: projectRoot });
    execFileSync('git', ['config', 'user.name', 'Native Test'], { cwd: projectRoot });
    await fs.writeFile(path.join(projectRoot, 'source.ts'), 'before\n');
    execFileSync('git', ['add', 'source.ts'], { cwd: projectRoot, stdio: 'ignore' });
    execFileSync('git', ['commit', '-m', 'baseline'], { cwd: projectRoot, stdio: 'ignore' });
  });

  afterEach(async () => {
    await fs.rm(projectRoot, { recursive: true, force: true });
  });

  it('fails closed when provenance names a non-local ref such as HEAD', async () => {
    const baseCommit = execFileSync('git', ['rev-parse', 'HEAD'], {
      cwd: projectRoot,
      encoding: 'utf8',
    }).trim();
    await fs.writeFile(path.join(projectRoot, 'source.ts'), 'after\n');
    execFileSync('git', ['add', 'source.ts'], { cwd: projectRoot, stdio: 'ignore' });
    execFileSync('git', ['commit', '-m', 'target change'], { cwd: projectRoot, stdio: 'ignore' });
    const targetCommit = execFileSync('git', ['rev-parse', 'HEAD'], {
      cwd: projectRoot,
      encoding: 'utf8',
    }).trim();
    const baseObject = execFileSync('git', ['rev-parse', `${baseCommit}:source.ts`], {
      cwd: projectRoot,
      encoding: 'utf8',
    }).trim();
    const targetObject = execFileSync('git', ['rev-parse', `${targetCommit}:source.ts`], {
      cwd: projectRoot,
      encoding: 'utf8',
    }).trim();

    expect(
      detectNativeGitExternalDrift({
        projectRoot,
        provenance: {
          provider: 'git',
          baseCommit,
          targetBranch: 'HEAD',
          targetCommit,
        },
        baseline: projection({ path: 'source.ts', gitObjectId: baseObject }),
        current: projection({ path: 'source.ts', gitObjectId: targetObject }),
        declaredArtifacts: [],
      }),
    ).toBeNull();
  });
});

import { promises as fs } from 'node:fs';
import os from 'node:os';
import path from 'node:path';

import { afterEach, beforeEach, describe, expect, it } from 'vitest';

import {
  parseNativeLocalExecution,
  readNativeLocalExecution,
  readOrRebuildNativeLocalExecution,
  rebuildNativeLocalExecution,
  writeNativeLocalExecution,
} from '../../../domains/comet-native/native-local-execution.js';
import { createNativePortableState } from '../../../domains/comet-native/native-portable-state.js';
import type { NativeLocalExecutionState } from '../../../domains/comet-native/native-portable-types.js';

describe('Native local execution overlay', () => {
  let root: string;
  let runtimeRoot: string;
  let file: string;

  beforeEach(async () => {
    root = await fs.mkdtemp(path.join(os.tmpdir(), 'comet-native-local-execution-'));
    runtimeRoot = path.join(root, '.comet', 'runtime', 'native');
    file = path.join(runtimeRoot, 'changes', 'portable-resume', 'state.json');
  });

  afterEach(async () => {
    await fs.rm(root, { recursive: true, force: true });
  });

  it('atomically round-trips a strict local-only state', async () => {
    const portableState = createNativePortableState({
      name: 'portable-resume',
      language: 'en',
      createdAt: '2026-08-09T00:00:00.000Z',
    });
    const state = rebuildNativeLocalExecution({ portableState, projectRoot: root });
    await writeNativeLocalExecution(file, state, { containedRoot: runtimeRoot });

    await expect(readNativeLocalExecution(file)).resolves.toEqual(state);
    expect(JSON.parse(await fs.readFile(file, 'utf8'))).toMatchObject({
      schema: 'comet.native.local-execution.v4',
      change: 'portable-resume',
      basedOnStateVersion: 1,
      execution: null,
      checks: [],
    });
    expect(() => parseNativeLocalExecution({ ...state, portableLoop: {} })).toThrow(
      /unknown field.*portableLoop/iu,
    );
  });

  it.each([
    ['missing', null],
    ['invalid', '{broken json'],
  ] as const)('rebuilds a %s overlay from portable state', async (expectedReason, contents) => {
    const portableState = {
      ...createNativePortableState({
        name: 'portable-resume',
        language: 'en',
        createdAt: '2026-08-09T00:00:00.000Z',
      }),
      state_version: 7,
      loop: {
        ...createNativePortableState({
          name: 'portable-resume',
          language: 'en',
          createdAt: '2026-08-09T00:00:00.000Z',
        }).loop,
        iteration: 3,
        no_progress_count: 2,
        next_action: 'Repair A2',
      },
    };
    if (contents !== null) {
      await fs.mkdir(path.dirname(file), { recursive: true });
      await fs.writeFile(file, contents, 'utf8');
    }

    const result = await readOrRebuildNativeLocalExecution({
      file,
      portableState,
      projectRoot: root,
      containedRoot: runtimeRoot,
    });

    expect(result).toMatchObject({ rebuilt: true, reason: expectedReason });
    expect(result.state).toMatchObject({ basedOnStateVersion: 7, execution: null, checks: [] });
    expect(portableState.loop).toMatchObject({
      iteration: 3,
      no_progress_count: 2,
      next_action: 'Repair A2',
    });
    await expect(readNativeLocalExecution(file)).resolves.toEqual(result.state);
  });

  it('discards a version-mismatched overlay instead of allowing JSON to override YAML', async () => {
    const portableState = {
      ...createNativePortableState({
        name: 'portable-resume',
        language: 'en',
        createdAt: '2026-08-09T00:00:00.000Z',
      }),
      state_version: 9,
    };
    const stale: NativeLocalExecutionState = {
      ...rebuildNativeLocalExecution({ portableState, projectRoot: root }),
      basedOnStateVersion: 8,
      execution: {
        operationId: 'old-operation',
        stage: 'verifying',
        actor: 'verifier',
        executionId: 'old-execution',
        status: 'running',
        startedAt: '2026-08-09T00:01:00.000Z',
        requestCheckRounds: 2,
      },
    };
    await writeNativeLocalExecution(file, stale, { containedRoot: runtimeRoot });

    const result = await readOrRebuildNativeLocalExecution({
      file,
      portableState,
      projectRoot: root,
      containedRoot: runtimeRoot,
    });

    expect(result).toMatchObject({ rebuilt: true, reason: 'version-mismatch' });
    expect(result.state).toMatchObject({
      basedOnStateVersion: 9,
      execution: null,
      checks: [],
    });
  });

  it('keeps a matching overlay and validates local check execution facts', async () => {
    const portableState = createNativePortableState({
      name: 'portable-resume',
      language: 'en',
      createdAt: '2026-08-09T00:00:00.000Z',
    });
    const state: NativeLocalExecutionState = {
      ...rebuildNativeLocalExecution({ portableState, projectRoot: root }),
      execution: {
        operationId: 'operation-1',
        stage: 'checking',
        actor: 'runtime',
        executionId: null,
        status: 'running',
        startedAt: '2026-08-09T00:01:00.000Z',
        requestCheckRounds: 0,
      },
      checks: [
        {
          id: 'unit-tests',
          name: 'Unit tests',
          operationId: 'operation-1',
          status: 'running',
          repeatable: true,
          timeoutMs: 10_000,
          executionCount: 1,
          argv: ['pnpm', 'vitest', 'run'],
          cwd: root,
          exitCode: null,
          startedAt: '2026-08-09T00:01:00.000Z',
          completedAt: null,
          log: 'logs/checks/unit-tests.log',
        },
      ],
    };
    await writeNativeLocalExecution(file, state, { containedRoot: runtimeRoot });

    const result = await readOrRebuildNativeLocalExecution({
      file,
      portableState,
      projectRoot: root,
      containedRoot: runtimeRoot,
    });
    expect(result).toEqual({ state, rebuilt: false, reason: null });

    expect(() =>
      parseNativeLocalExecution({
        ...state,
        checks: [{ ...state.checks[0], secretSummary: 'not allowed' }],
      }),
    ).toThrow(/unknown field.*secretSummary/iu);
  });
});

