async function candidate() {
  const root = await fs.mkdtemp(path.join(os.tmpdir(), 'comet-check-termination-'));
  roots.push(root);
  await writeProjectConfig(root, defaultProjectConfig('docs', 'en'));
  const paths = await nativeProjectPaths(root, 'docs');
  await ensureNativeDirectories(paths);
  await createNativePortableChange({ paths, name: 'change', language: 'en' });
  await fs.writeFile(
    path.join(nativePortableChangeDir(paths, 'change'), 'brief.md'),
    '# Acceptance examples\n- Unconfirmed checks cannot overlap a retry.\n',
  );
  const state = await confirmNativePortableShape({ paths, name: 'change' });
  const runner = createNativeRunnerChannel();
  await submitNativePortableBuilderCandidate({
    paths,
    name: state.name,
    input: {
      identity: runner.captureExecutionIdentity({
        identityProvider: 'test-host',
        executionRef: 'builder',
      }),
      candidateId: 'candidate',
      summary: 'Implemented.',
      addressedAcceptanceIds: ['A1'],
      acceptanceReview: fixtureAcceptanceReview(['A1']),
      review: {
        status: 'passed',
        summary: 'Independent review passed.',
        reviewerExecutionRef: 'reviewer',
      },
    },
  });
  return { paths, runner };
}

describe('Native portable unconfirmed check termination', () => {
  it('resolves an explicit empty check plan once before dispatching the Verifier', async () => {
    const { paths } = await candidate();
    const file = nativeLocalExecutionFile(paths, 'change');
    const before = await readNativeLocalExecution(file);
    expect(before?.execution).toBeNull();
    await expect(
      dispatchNativePortableVerifier({ paths, name: 'change', checks: [] }),
    ).rejects.toThrow('must be explicitly resolved');
    expect(await readNativeLocalExecution(file)).toEqual(before);
    const execute = vi.spyOn(checkExecutor, 'executeNativeCheck');
    const first = await executeNativePortableCheckPlan({ paths, name: 'change', plans: [] });
    expect(first).toMatchObject({ disposition: 'executed', checks: [] });
    const completed = await readNativeLocalExecution(file);
    expect(completed).toMatchObject({
      execution: { stage: 'checking', actor: 'runtime', status: 'completed' },
      checks: [],
    });
    await expect(
      executeNativePortableCheckPlan({ paths, name: 'change', plans: [] }),
    ).resolves.toMatchObject({ disposition: 'reused', checks: [] });
    expect(await readNativeLocalExecution(file)).toEqual(completed);
    expect(execute).not.toHaveBeenCalled();
    await dispatchNativePortableVerifier({ paths, name: 'change', checks: [] });
    expect(await readNativeLocalExecution(file)).toMatchObject({
      execution: { actor: 'verifier', status: 'running' },
    });
    const verifying = await readNativeLocalExecution(file);
    await expect(
      executeNativePortableCheckPlan({ paths, name: 'change', plans: [] }),
    ).resolves.toMatchObject({ disposition: 'reused', checks: [] });
    expect(await readNativeLocalExecution(file)).toEqual(verifying);
    expect(execute).not.toHaveBeenCalled();
  });

  it('preserves completed check receipts when an empty plan is requested', async () => {
    const { paths } = await candidate();
    const execute = vi.spyOn(checkExecutor, 'executeNativeCheck');
    const original = await executeNativePortableCheckPlan({
      paths,
      name: 'change',
      plans: [
        {
          id: 'existing',
          name: 'Existing check',
          executable: process.execPath,
          argv: ['-e', 'process.exit(0)'],
          cwdRef: '.',
          timeoutMs: 10000,
          repeatable: true,
        },
      ],
    });
    const file = nativeLocalExecutionFile(paths, 'change');
    const completed = await readNativeLocalExecution(file);
    expect(original.checks).toMatchObject([{ id: 'existing', status: 'passed' }]);
    await expect(
      executeNativePortableCheckPlan({ paths, name: 'change', plans: [] }),
    ).resolves.toMatchObject({ disposition: 'reused', checks: original.checks });
    expect(await readNativeLocalExecution(file)).toEqual(completed);
    expect(execute).toHaveBeenCalledTimes(1);
  });

  it('dispatches an explicit empty check plan through the generated Native next bundle', async () => {
    const { paths } = await candidate();
    const input = path.join(paths.workspaceRuntimeRoot, 'empty-check-plan.json');
    await fs.writeFile(input, JSON.stringify({ kind: 'dispatch-verifier', checks: [] }));
    const result = spawnSync(
      process.execPath,
      [
        path.resolve('assets/skills/comet-native/scripts/comet-native-next.mjs'),
        'change',
        '--runner-input',
        input,
        '--project-root',
        paths.projectRoot,
        '--json',
      ],
      { cwd: paths.projectRoot, encoding: 'utf8', windowsHide: true, timeout: 20_000 },
    );
    expect(result.status, result.stdout + result.stderr).toBe(0);
    expect(JSON.parse(result.stdout)).toMatchObject({
      exitCode: 0,
      data: { checks: [], state: { phase: 'verify', loop: { attempt: 1 } } },
    });
    expect(await readNativeLocalExecution(nativeLocalExecutionFile(paths, 'change'))).toMatchObject(
      {
        execution: { actor: 'verifier', status: 'running' },
        checks: [],
      },
    );
  });

  it('persists an Agent-confirmed interruption before allowing an explicit check retry', async () => {
    const { paths } = await candidate();
    const plan = {
      id: 'orphaned',
      name: 'Orphaned check',
      executable: process.execPath,
      argv: ['-e', 'process.exit(0)'],
      cwdRef: '.',
      timeoutMs: 10000,
      repeatable: true,
    };
    const failure = new checkExecutor.NativeCheckTerminationUnconfirmedError();
    const execute = vi
      .spyOn(checkExecutor, 'executeNativeCheck')
      .mockImplementationOnce(async ({ onSpawn }) => {
        await onSpawn?.({
          instanceId: 'original-check-instance',
          signal: new AbortController().signal,
        });
        throw failure;
      });
    const ordinary = () => executeNativePortableCheckPlan({ paths, name: 'change', plans: [plan] });
    await expect(ordinary()).rejects.toBe(failure);
    const file = nativeLocalExecutionFile(paths, 'change');
    const running = (await readNativeLocalExecution(file))!;
    expect(running).toMatchObject({
      execution: { stage: 'checking', status: 'running' },
      checks: [{ id: plan.id, status: 'running', executionCount: 1 }],
    });
    await expect(ordinary()).rejects.toThrow('原检查或验收仍在执行');
    expect(await readNativeLocalExecution(file)).toEqual(running);
    expect(execute).toHaveBeenCalledTimes(1);
    const [target] = await inspectNativeCheckStopEvidenceTargets(paths, 'change');
    const proofFile = path.join(paths.projectRoot, 'stop-confirmation.json');
    await fs.writeFile(
      proofFile,
      JSON.stringify([
        {
          ...target.confirmation,
          evidence:
            'The original command and descendants were stopped; actual logs were inspected.',
        },
      ]),
    );
    await nativeDoctorCommand(
      ['change', '--repair', '--confirmed', '--stopped-actions', proofFile],
      paths.projectRoot,
    );
    await expect(ordinary()).resolves.toMatchObject({
      disposition: 'reused',
      checks: [{ id: plan.id, status: 'interrupted' }],
    });
    const interrupted = {
      ...running,
      execution: { ...running.execution!, status: 'interrupted' },
      checks: running.checks.map((check) => ({
        ...check,
        status: 'interrupted',
        activeProcess: null,
      })),
    };
    expect(await readNativeLocalExecution(file)).toEqual(interrupted);
    await expect(ordinary()).resolves.toMatchObject({
      checks: [{ id: plan.id, status: 'interrupted' }],
    });
    expect(await readNativeLocalExecution(file)).toEqual(interrupted);
    expect(execute).toHaveBeenCalledTimes(1);
    await expect(
      retryNativePortableCheckPlan({ paths, name: 'change', checkIds: [plan.id] }),
    ).resolves.toMatchObject({ checks: [{ id: plan.id, status: 'passed' }] });
    expect(execute).toHaveBeenCalledTimes(2);
    expect(await readNativeLocalExecution(file)).toMatchObject({
      execution: { status: 'completed' },
      checks: [{ id: plan.id, status: 'passed', executionCount: 2 }],
    });
  });

  it.each(['runtime', 'verifier', 'legacy-verifier'] as const)(
    'preserves the registered process and blocks retries for %s checks',
    async (source) => {
      const { paths, runner } = await candidate();
      const plan = {
        id: 'pending',
        name: 'Pending check',
        executable: process.execPath,
        argv: ['-e', 'process.exit(0)'],
        cwdRef: '.',
        timeoutMs: 10000,
        repeatable: true,
      };
      if (source !== 'runtime') {
        const baseline = await executeNativePortableCheckPlan({ paths, name: 'change', plans: [] });
        await dispatchNativePortableVerifier({
          paths,
          name: 'change',
          checks: baseline.checks,
          verifierExecutionId: 'verifier',
        });
      }
      const failure = new checkExecutor.NativeCheckTerminationUnconfirmedError();
      const execute = vi
        .spyOn(checkExecutor, 'executeNativeCheck')
        .mockImplementation(async ({ onSpawn }) => {
          await onSpawn?.({
            instanceId: 'original-check-instance',
            signal: new AbortController().signal,
          });
          throw failure;
        });
      const attempt = () =>
        source === 'runtime'
          ? executeNativePortableCheckPlan({ paths, name: 'change', plans: [plan] })
          : submitNativePortableVerifierResult({
              paths,
              name: 'change',
              checks: [],
              maxVerifyFailures: 5,
              envelope: runner.envelopeVerifierResponse({
                candidateId: 'candidate',
                identity: runner.captureExecutionIdentity({
                  identityProvider: 'test-host',
                  executionRef: 'verifier',
                }),
                payload: {
                  kind: 'request-checks',
                  iteration: 1,
                  attempt: 1,
                  checks: [plan],
                },
              }),
            });
      await expect(attempt()).rejects.toBe(failure);
      const file = nativeLocalExecutionFile(paths, 'change');
      const local = (await readNativeLocalExecution(file))!;
      expect(local).toMatchObject({
        execution: { stage: 'checking', actor: 'runtime', status: 'running' },
        checks: [
          {
            id: 'pending',
            status: 'running',
            executionCount: 1,
            activeProcess: { status: 'running', instanceId: 'original-check-instance' },
          },
        ],
      });
      expect((await readNativePortableChange(paths, 'change')).loop.execution_failure_count).toBe(
        0,
      );
      await expect(
        executeNativePortableCheckPlan({ paths, name: 'change', plans: [] }),
      ).rejects.toThrow();
      expect(await readNativeLocalExecution(file)).toEqual(local);
      await expect(attempt()).rejects.toThrow();
      await expect(
        retryNativePortableCheckPlan({ paths, name: 'change', checkIds: ['pending'] }),
      ).rejects.toThrow();
      expect(execute).toHaveBeenCalledTimes(1);

      // A pre-upgrade request-checks overlay can legally lack verifier_action.
      if (source === 'legacy-verifier') {
        const legacy = await readNativePortableChange(paths, 'change');
        delete legacy.verifier_action;
        await writeNativePortableState(nativePortableStateFile(paths, 'change'), legacy);
      }

      // 模拟 owner 已退出，但检查树没有整树停止证据。
      await fs.writeFile(file, JSON.stringify(local));
      await expect(inspectNativePortableCheckExecution(local)).resolves.toBe('unknown');
      await expect(recoverNativePortableChange({ paths, name: 'change' })).resolves.toMatchObject({
        action: 'await-user',
        reason: 'execution-active',
      });
      await expect(
        recoverNativePortableChange({ paths, name: 'change', recoverUnknownRuntimeCheck: true }),
      ).resolves.toMatchObject({ action: 'await-user', reason: 'execution-active' });
      const diagnostic = await nativeDoctorCommand(['change'], paths.projectRoot);
      expect(diagnostic).toMatchObject({
        exitCode: 65,
        data: {
          findings: [
            {
              code: 'portable-check-execution-stuck',
              message: expect.stringContaining('original Runtime command has no completed result'),
            },
          ],
        },
      });
      const finding = (diagnostic.data as { findings: Array<{ repair?: string }> }).findings[0];
      expect(finding.repair).toBeUndefined();
      await expect(
        nativeDoctorCommand(['change', '--repair'], paths.projectRoot),
      ).resolves.toMatchObject({
        exitCode: 65,
        data: { healthy: false, repaired: false, result: { reason: 'execution-active' } },
      });
      expect(await readNativeLocalExecution(file)).toEqual(local);
      expect(execute).toHaveBeenCalledTimes(1);

      const [target] = await inspectNativeCheckStopEvidenceTargets(paths, 'change');
      expect(target.canConfirm).toBe(true);
      const confirmation = {
        ...target.confirmation,
        evidence:
          'The host process inventory confirms the original check and all descendants stopped.',
      };
      const recover = (entries: unknown = [confirmation]) =>
        recoverNativeChecksWithStopEvidence({ paths, name: 'change', confirmations: entries });
      for (const invalid of [
        { ...confirmation, operationId: 'another-operation' },
        { ...confirmation, executionHash: '0'.repeat(64) },
        { ...confirmation, evidence: '' },
        target.confirmation,
      ]) {
        await expect(recover([invalid])).rejects.toThrow();
        expect(await readNativeLocalExecution(file)).toEqual(local);
      }
      const starting = structuredClone(local);
      starting.checks[0].activeProcess = { status: 'starting' };
      await fs.writeFile(file, JSON.stringify(starting));
      const [unregistered] = await inspectNativeCheckStopEvidenceTargets(paths, 'change');
      await expect(recover([confirmation])).rejects.toThrow();
      expect(await readNativeLocalExecution(file)).toEqual(starting);
      await fs.writeFile(file, JSON.stringify(local));

      const originalWrite = atomicFile.atomicWriteJson;
      const write = vi
        .spyOn(atomicFile, 'atomicWriteJson')
        .mockImplementation(async (targetFile, value, settings) => {
          if (String(targetFile).includes(`${path.sep}check-stops${path.sep}`))
            throw new Error('receipt write failed');
          return originalWrite(targetFile, value, settings);
        });
      await expect(recover()).rejects.toThrow('receipt write failed');
      expect(await readNativeLocalExecution(file)).toEqual(local);
      write.mockRestore();

      const proofFile = path.join(paths.workspaceRuntimeRoot, 'check-stop-confirmation.json');
      await fs.writeFile(proofFile, JSON.stringify([confirmation]));
      await expect(
        nativeDoctorCommand(
          ['change', '--repair', '--stopped-actions', proofFile],
          paths.projectRoot,
        ),
      ).rejects.toThrow('--confirmed');
      const command = () =>
        nativeDoctorCommand(
          ['change', '--repair', '--confirmed', '--stopped-actions', proofFile],
          paths.projectRoot,
        );
      if (source === 'runtime') {
        const failLocal = vi
          .spyOn(atomicFile, 'atomicWriteJson')
          .mockImplementation(async (targetFile, value, settings) => {
            if (targetFile === file) throw new Error('local write failed');
            return originalWrite(targetFile, value, settings);
          });
        await expect(command()).rejects.toThrow('local write failed');
        failLocal.mockRestore();
      }
      if (source !== 'runtime') {
        const failLocal = vi
          .spyOn(atomicFile, 'atomicWriteJson')
          .mockImplementation(async (targetFile, value, settings) => {
            if (targetFile === file) throw new Error('local write failed');
            return originalWrite(targetFile, value, settings);
          });
        await expect(command()).rejects.toThrow('local write failed');
        failLocal.mockRestore();
        const failApplied = vi
          .spyOn(atomicFile, 'atomicWriteJson')
          .mockImplementation(async (targetFile, value, settings) => {
            if (
              (value as { schema?: string; applied?: boolean }).schema ===
                'comet.native.check-stop-evidence.v1' &&
              (value as { applied?: boolean }).applied
            )
              throw new Error('applied write failed');
            return originalWrite(targetFile, value, settings);
          });
        await expect(command()).rejects.toThrow('applied write failed');
        failApplied.mockRestore();
      }
      const recovered = await command();
      expect(recovered).toMatchObject({
        data: {
          repaired: source === 'runtime',
          stoppedChecks: { alreadyApplied: source !== 'runtime' },
        },
      });
      const recoveredLocal = (await readNativeLocalExecution(file))!;
      expect(recoveredLocal.checks).toMatchObject([
        { status: 'interrupted', executionCount: 1, activeProcess: null },
      ]);
      expect((await readNativePortableChange(paths, 'change')).loop.execution_failure_count).toBe(
        source !== 'runtime' ? 1 : 0,
      );
      const receiptRef = (recovered.data as { stoppedChecks: { receiptRef: string } }).stoppedChecks
        .receiptRef;
      const receiptFile = path.join(nativePreferredChangeRuntimeDir(paths, 'change'), receiptRef);
      const receipt = await fs.readFile(receiptFile, 'utf8');
      expect(JSON.parse(receipt)).toMatchObject({
        applied: true,
        before: { local },
        confirmations: [confirmation],
      });
      await expect(command()).resolves.toMatchObject({
        data: { repaired: false, stoppedChecks: { alreadyApplied: true } },
      });
      expect(await fs.readFile(receiptFile, 'utf8')).toBe(receipt);
      expect(await readNativeLocalExecution(file)).toEqual(recoveredLocal);
      expect(execute).toHaveBeenCalledTimes(1);

      // Even a receipt with a recomputed checksum cannot authorize a passed result.
      const forged = JSON.parse(receipt);
      forged.after.local.checks[0].status = 'passed';
      forged.recoveryHash = canonicalHash('comet.native.check-stop-recovery.v1', {
        before: forged.before,
        after: forged.after,
      });
      await fs.writeFile(receiptFile, JSON.stringify(forged));
      await expect(command()).rejects.toThrow('不合法的恢复结果');
      expect(await readNativeLocalExecution(file)).toEqual(recoveredLocal);
      await fs.writeFile(receiptFile, receipt);
      if (source === 'legacy-verifier') {
        const next = await readNativePortableChange(paths, 'change');
        expect(next.verifier_action).toBeUndefined();
        expect(next.loop.next_action).toBe('dispatch-new-verifier');
      }

      const newer = structuredClone(recoveredLocal);
      newer.execution!.operationId = 'new-completed-operation';
      newer.execution!.status = 'completed';
      for (const check of newer.checks) check.operationId = newer.execution!.operationId;
      await fs.writeFile(file, JSON.stringify(newer));
      await expect(command()).rejects.toThrow('旧证明');
      expect(await readNativeLocalExecution(file)).toEqual(newer);
    },
  );
});

import { describe, expect, it } from 'vitest';

import { buildNativeContractSnapshot } from '../../../domains/comet-native/native-contract.js';
import {
  acceptLatestNativeRepairOverride,
  acceptNativeRepairOverride,
  buildNativeRepairSignatureFromEvidence,
  inspectLatestNativeRepairProjection,
  inspectNativeRepairFailure,
  inspectNativeRepairResume,
  nativeRepairFailureFacts,
  nativeRepairScopeHash,
  NATIVE_REPAIR_TRAJECTORY_FIELD,
  NATIVE_REPAIR_TRAJECTORY_LIMITS,
  parseNativeRepairTrajectoryProjection,
  rebuildNativeRepairHistory,
  type NativeRepairEvidenceInput,
  type NativeRepairTrajectoryProjection,
} from '../../../domains/comet-native/native-repair-runtime.js';
import {
  buildNativeAcceptanceEvidenceTrace,
  buildNativeVerificationEvidenceEnvelope,
} from '../../../domains/comet-native/native-verification-evidence.js';
import type { NativeContentSnapshotManifest } from '../../../domains/comet-native/native-types.js';
import { buildNativeImplementationScopeBundle } from '../../../domains/comet-native/native-verification-scope.js';

const RUN_ID = 'repair-run';
const NOW = new Date('2026-07-17T00:00:00.000Z');

function snapshot(hash: string): NativeContentSnapshotManifest {
  return {
    schema: 'comet.native.content-snapshot.v1',
    origin: 'explicit',
    createdAt: NOW.toISOString(),
    complete: true,
    limits: {
      maxFiles: 10,
      maxFileBytes: 1_024,
      maxTotalBytes: 4_096,
      maxManifestBytes: 4_096,
    },
    entries: [{ path: 'src/feature.ts', hash, size: 10, type: 'file' }],
    omitted: [],
    omittedCount: 0,
  };
}

function evidenceInput(
  result: 'pass' | 'fail' = 'fail',
  currentHash = 'b'.repeat(64),
): NativeRepairEvidenceInput & { maxVerifyFailures: number } {
  const contract = buildNativeContractSnapshot({
    briefMarkdown: '# Acceptance examples\n- The repaired behavior works.\n',
    specs: [],
  });
  const implementationScope = buildNativeImplementationScopeBundle({
    baseline: snapshot('a'.repeat(64)),
    current: snapshot(currentHash),
    contractHash: contract.contractHash,
    declaredArtifacts: [{ path: 'src/feature.ts', kind: 'file' }],
  });
  const acceptanceTrace = buildNativeAcceptanceEvidenceTrace(
    contract.acceptance,
    contract.acceptance.map((criterion) => ({
      acceptance_id: criterion.id,
      status: result === 'fail' ? ('failed' as const) : ('passed' as const),
      evidence_refs: result === 'fail' ? [] : [`runtime/evidence/receipts/${'a'.repeat(64)}.json`],
      ...(result === 'fail' ? { skipped_reason: 'The acceptance is not satisfied.' } : {}),
    })),
    { nativeRootRef: 'comet' },
  );
  const envelope = buildNativeVerificationEvidenceEnvelope({
    change: 'repair-loop',
    sourceRevision: 3,
    result,
    contractHash: contract.contractHash,
    acceptanceHash: contract.acceptanceHash,
    implementationScope: {
      ref: `runtime/evidence/scopes/${implementationScope.scope.scopeHash}.json`,
      bundle: implementationScope,
    },
    reportRef: 'verification.md',
    reportHash: 'c'.repeat(64),
    acceptanceTrace,
    requiredReceiptRefs: [`runtime/evidence/receipts/${'b'.repeat(64)}.json`],
    now: NOW,
  });
  return { envelope, implementationScope, maxVerifyFailures: 5 };
}

function unchangedEvidenceInput(
  noCodeReason: string,
): NativeRepairEvidenceInput & { maxVerifyFailures: number } {
  const contract = buildNativeContractSnapshot({
    briefMarkdown: '# Acceptance examples\n- The no-code behavior remains valid.\n',
    specs: [],
  });
  const baseline = snapshot('a'.repeat(64));
  const implementationScope = buildNativeImplementationScopeBundle({
    baseline,
    current: { ...baseline, createdAt: new Date(NOW.valueOf() + 1_000).toISOString() },
    contractHash: contract.contractHash,
    declaredArtifacts: [],
    noCodeReason,
  });
  const acceptanceTrace = buildNativeAcceptanceEvidenceTrace(
    contract.acceptance,
    contract.acceptance.map((criterion) => ({
      acceptance_id: criterion.id,
      status: 'failed' as const,
      evidence_refs: [],
      skipped_reason: 'The acceptance is not satisfied.',
    })),
    { nativeRootRef: 'comet' },
  );
  const envelope = buildNativeVerificationEvidenceEnvelope({
    change: 'repair-loop',
    sourceRevision: 3,
    result: 'fail',
    contractHash: contract.contractHash,
    acceptanceHash: contract.acceptanceHash,
    implementationScope: {
      ref: `runtime/evidence/scopes/${implementationScope.scope.scopeHash}.json`,
      bundle: implementationScope,
    },
    reportRef: 'verification.md',
    reportHash: 'c'.repeat(64),
    acceptanceTrace,
    requiredReceiptRefs: [`runtime/evidence/receipts/${'b'.repeat(64)}.json`],
    now: NOW,
  });
  return { envelope, implementationScope, maxVerifyFailures: 5 };
}

function event(
  sequence: number,
  data: Record<string, unknown>,
  overrides: Record<string, unknown> = {},
): unknown {
  return {
    sequence,
    timestamp: new Date(NOW.valueOf() + sequence * 1_000).toISOString(),
    type: 'state_transitioned',
    runId: RUN_ID,
    data,
    ...overrides,
  };
}

function repairEvent(
  sequence: number,
  projection: NativeRepairTrajectoryProjection,
  implementationScopeHash?: string,
): unknown {
  return event(sequence, {
    previousPhase: 'verify',
    nextPhase: 'build',
    verificationResult: 'fail',
    ...(implementationScopeHash ? { implementationScopeHash } : {}),
    [NATIVE_REPAIR_TRAJECTORY_FIELD]: projection,
  });
}

function overrideEvent(sequence: number, projection: NativeRepairTrajectoryProjection): unknown {
  return event(sequence, {
    previousPhase: 'build',
    nextPhase: 'verify',
    verificationResult: null,
    [NATIVE_REPAIR_TRAJECTORY_FIELD]: projection,
  });
}

function committed(trajectory: readonly unknown[]) {
  return {
    trajectory,
    committedTrajectoryOffset: trajectory.length,
    runId: RUN_ID,
  };
}

describe('Native repair runtime integration', () => {
  it('derives a lightweight default signature from failed, content-bound evidence', () => {
    const input = evidenceInput();
    const facts = nativeRepairFailureFacts(input);
    const signature = buildNativeRepairSignatureFromEvidence(input);

    expect(facts).toMatchObject({
      contractHash: input.envelope.contractHash,
      implementationScopeHash: nativeRepairScopeHash(input.implementationScope),
      artifactSnapshotHash: input.implementationScope.scope.currentProjectionHash,
      failedCheckIds: [],
    });
    expect(signature.signatureHash).toMatch(/^[a-f0-9]{64}$/u);
  });

  it('keeps one repair episode when only the no-code explanation is reworded', () => {
    const first = unchangedEvidenceInput('No project edit is required.');
    const reworded = unchangedEvidenceInput('The project intentionally remains unchanged.');
    const firstSignature = buildNativeRepairSignatureFromEvidence(first).signatureHash;
    const rewordedSignature = buildNativeRepairSignatureFromEvidence(reworded).signatureHash;
    const repairScopeHash = nativeRepairScopeHash(reworded.implementationScope);

    expect(reworded.implementationScope.scope.scopeHash).not.toBe(
      first.implementationScope.scope.scopeHash,
    );
    expect(rewordedSignature).toBe(firstSignature);
    expect(
      rebuildNativeRepairHistory(
        committed([
          repairEvent(1, {
            signatureHash: firstSignature,
            disposition: 'continue',
            overrideSummaryHash: null,
          }),
          event(2, {
            previousPhase: 'build',
            nextPhase: 'verify',
            verificationResult: null,
            implementationScopeHash: reworded.implementationScope.scope.scopeHash,
            repairScopeHash,
          }),
          repairEvent(3, {
            signatureHash: rewordedSignature,
            disposition: 'warn',
            overrideSummaryHash: null,
          }),
        ]),
      ),
    ).toMatchObject([
      { kind: 'failure', iteration: 1, signatureHash: firstSignature },
      { kind: 'failure', iteration: 2, signatureHash: firstSignature },
    ]);

    expect(
      inspectNativeRepairResume({
        ...first,
        ...committed([
          repairEvent(1, {
            signatureHash: firstSignature,
            disposition: 'continue',
            overrideSummaryHash: null,
          }),
          repairEvent(2, {
            signatureHash: firstSignature,
            disposition: 'warn',
            overrideSummaryHash: null,
          }),
          repairEvent(3, {
            signatureHash: firstSignature,
            disposition: 'manual-stop',
            overrideSummaryHash: null,
          }),
        ]),
        currentImplementationScope: reworded.implementationScope,
      }),
    ).toMatchObject({ disposition: 'override-required', reason: 'override-required' });
  });

  it('continues once, warns on the repeat, then persists a manual stop', () => {
    const evidence = evidenceInput();
    const first = inspectNativeRepairFailure({ ...evidence, ...committed([]) });
    expect(first).toMatchObject({
      decision: { disposition: 'continue', consecutiveFailures: 1 },
      eventProjection: { disposition: 'continue', overrideSummaryHash: null },
    });

    const firstEvent = repairEvent(1, first.eventProjection!);
    const second = inspectNativeRepairFailure({ ...evidence, ...committed([firstEvent]) });
    expect(second).toMatchObject({
      decision: { disposition: 'warn', consecutiveFailures: 2 },
      eventProjection: { disposition: 'warn', overrideSummaryHash: null },
    });

    const third = inspectNativeRepairFailure({
      ...evidence,
      ...committed([firstEvent, repairEvent(2, second.eventProjection!)]),
    });
    expect(third).toMatchObject({
      decision: { disposition: 'manual-stop', consecutiveFailures: 3 },
      eventProjection: { disposition: 'manual-stop', overrideSummaryHash: null },
    });
  });

  it('accepts one matching override on the latest manual stop and rejects a second one', () => {
    const evidence = evidenceInput();
    const first = inspectNativeRepairFailure({ ...evidence, ...committed([]) });
    const one = repairEvent(1, first.eventProjection!);
    const second = inspectNativeRepairFailure({ ...evidence, ...committed([one]) });
    const two = repairEvent(2, second.eventProjection!);
    const third = inspectNativeRepairFailure({ ...evidence, ...committed([one, two]) });
    const three = repairEvent(3, third.eventProjection!);
    const expectedSignatureHash = first.decision.signature.signatureHash;

    expect(
      inspectNativeRepairResume({
        ...evidence,
        ...committed([one, two, three]),
        currentImplementationScope: evidence.implementationScope,
      }),
    ).toMatchObject({
      disposition: 'override-required',
      reason: 'override-required',
      signatureHash: expectedSignatureHash,
    });

    const historyOnly = acceptLatestNativeRepairOverride({
      ...committed([one, two, three]),
      override: {
        expectedSignatureHash,
        summary: 'Try the independent compatibility path once.',
      },
    });
    const accepted = acceptNativeRepairOverride({
      ...evidence,
      ...committed([one, two, three]),
      override: {
        expectedSignatureHash,
        summary: 'Try the independent compatibility path once.',
      },
    });
    expect(accepted).toMatchObject({
      decision: { disposition: 'continue', reasonCode: 'override-accepted' },
      eventProjection: {
        signatureHash: expectedSignatureHash,
        disposition: 'continue',
      },
    });
    expect(historyOnly.eventProjection).toEqual(accepted.eventProjection);
    expect(accepted.eventProjection?.overrideSummaryHash).toMatch(/^[a-f0-9]{64}$/u);
    expect(Object.keys(accepted.eventProjection!).sort()).toEqual([
      'contractHash',
      'disposition',
      'failedAcceptanceIds',
      'failedCheckIds',
      'maxVerifyFailures',
      'overrideSummaryHash',
      'signatureHash',
    ]);

    const four = overrideEvent(4, accepted.eventProjection!);
    expect(inspectLatestNativeRepairProjection(committed([one, two, three, four]))).toEqual(
      accepted.eventProjection,
    );
    const refused = acceptNativeRepairOverride({
      ...evidence,
      ...committed([one, two, three, four]),
      override: {
        expectedSignatureHash,
        summary: 'A second override must not be accepted.',
      },
    });
    expect(refused).toMatchObject({
      decision: { disposition: 'manual-stop', reasonCode: 'override-already-used' },
      eventProjection: null,
    });
    expect(refused.history.slice(-2)).toEqual([
      {
        kind: 'failure',
        revision: 3,
        iteration: 3,
        signatureHash: expectedSignatureHash,
        failedAcceptanceIds: evidence.envelope.acceptanceTrace.entries
          .filter((entry) => entry.status === 'failed' || entry.status === 'missing')
          .map((entry) => entry.acceptanceId),
        failedCheckIds: [],
      },
      {
        kind: 'override',
        revision: 4,
        iteration: 3,
        signatureHash: expectedSignatureHash,
        summaryHash: accepted.eventProjection!.overrideSummaryHash,
      },
    ]);
    expect(() =>
      acceptLatestNativeRepairOverride({
        ...committed([one, two, three, four]),
        override: {
          expectedSignatureHash,
          summary: 'No repeated override.',
        },
      }),
    ).toThrow('latest manual stop');

    const five = repairEvent(5, {
      signatureHash: expectedSignatureHash,
      disposition: 'manual-stop',
      overrideSummaryHash: null,
    });
    expect(() =>
      acceptLatestNativeRepairOverride({
        ...committed([one, two, three, four, five]),
        override: {
          expectedSignatureHash,
          summary: 'The signature already used its only override.',
        },
      }),
    ).toThrow('already overridden');
    expect(
      inspectNativeRepairResume({
        ...evidence,
        ...committed([one, two, three, four, five]),
        currentImplementationScope: evidence.implementationScope,
      }),
    ).toMatchObject({ disposition: 'hard-stop', reason: 'override-already-applied' });
  });

  it('treats a new Build scope as progress without requiring an override', () => {
    const evidence = evidenceInput();
    const signature = buildNativeRepairSignatureFromEvidence(evidence).signatureHash;
    const trajectory = [
      repairEvent(1, {
        signatureHash: signature,
        disposition: 'continue',
        overrideSummaryHash: null,
      }),
      repairEvent(2, {
        signatureHash: signature,
        disposition: 'warn',
        overrideSummaryHash: null,
      }),
      repairEvent(3, {
        signatureHash: signature,
        disposition: 'manual-stop',
        overrideSummaryHash: null,
      }),
    ];
    const progressed = evidenceInput('fail', 'd'.repeat(64));

    expect(
      inspectNativeRepairResume({
        ...evidence,
        ...committed(trajectory),
        currentImplementationScope: progressed.implementationScope,
      }),
    ).toMatchObject({ disposition: 'proceed', reason: 'scope-progress' });
  });

  it('starts a fresh episode after scope progress following an ordinary failure', () => {
    const first = evidenceInput('fail', 'b'.repeat(64));
    const progressed = evidenceInput('fail', 'd'.repeat(64));
    const firstSignature = buildNativeRepairSignatureFromEvidence(first).signatureHash;
    const progressedSignature = buildNativeRepairSignatureFromEvidence(progressed).signatureHash;
    const trajectory = [
      repairEvent(
        1,
        {
          signatureHash: firstSignature,
          disposition: 'continue',
          overrideSummaryHash: null,
        },
        first.implementationScope.scope.scopeHash,
      ),
      event(2, {
        previousPhase: 'build',
        nextPhase: 'verify',
        verificationResult: null,
        implementationScopeHash: progressed.implementationScope.scope.scopeHash,
      }),
      repairEvent(
        3,
        {
          signatureHash: progressedSignature,
          disposition: 'continue',
          overrideSummaryHash: null,
        },
        progressed.implementationScope.scope.scopeHash,
      ),
    ];

    expect(rebuildNativeRepairHistory(committed(trajectory))).toEqual([
      {
        kind: 'failure',
        revision: 3,
        iteration: 1,
        signatureHash: progressedSignature,
      },
    ]);
  });

  it('hard-stops the configured fifth total failure and never applies an override there', () => {
    const evidence = evidenceInput();
    const trajectory = Array.from({ length: 4 }, (_, index) =>
      repairEvent(index + 1, {
        signatureHash: index.toString(16).padStart(64, '0'),
        disposition: 'continue',
        overrideSummaryHash: null,
      }),
    );
    const currentSignature = buildNativeRepairSignatureFromEvidence(evidence).signatureHash;
    const stopped = inspectNativeRepairFailure({ ...evidence, ...committed(trajectory) });
    expect(stopped).toMatchObject({
      decision: { disposition: 'hard-stop', totalRepairFailures: 5 },
      eventProjection: { disposition: 'hard-stop', overrideSummaryHash: null },
    });
    const persisted = [...trajectory, repairEvent(5, stopped.eventProjection!)];
    expect(inspectLatestNativeRepairProjection(committed(persisted))).toEqual(
      stopped.eventProjection,
    );
    const progressed = evidenceInput('fail', 'e'.repeat(64));
    expect(
      inspectNativeRepairResume({
        ...evidence,
        ...committed(persisted),
        currentImplementationScope: progressed.implementationScope,
      }),
    ).toMatchObject({ disposition: 'hard-stop', reason: 'hard-stop' });
    const result = acceptNativeRepairOverride({
      ...evidence,
      ...committed(persisted),
      override: {
        expectedSignatureHash: currentSignature,
        summary: 'The hard stop must win.',
      },
    });

    expect(result).toMatchObject({
      decision: { disposition: 'hard-stop', totalRepairFailures: 5 },
      eventProjection: null,
    });
    expect(() =>
      acceptLatestNativeRepairOverride({
        ...committed(persisted),
        override: {
          expectedSignatureHash: currentSignature,
          summary: 'The hard stop must still win.',
        },
      }),
    ).toThrow('hard stop cannot be overridden');
  });

  it('uses only the committed prefix and ignores ordinary transition events', () => {
    const signature = buildNativeRepairSignatureFromEvidence(evidenceInput()).signatureHash;
    const ordinary = event(1, {
      previousPhase: 'shape',
      nextPhase: 'build',
      verificationResult: null,
    });
    const projected = repairEvent(2, {
      signatureHash: signature,
      disposition: 'continue',
      overrideSummaryHash: null,
    });
    const uncommitted = repairEvent(3, {
      signatureHash: signature,
      disposition: 'warn',
      overrideSummaryHash: null,
    });

    expect(
      rebuildNativeRepairHistory({
        trajectory: [ordinary, projected, uncommitted],
        committedTrajectoryOffset: 2,
        runId: RUN_ID,
      }),
    ).toEqual([{ kind: 'failure', revision: 2, iteration: 1, signatureHash: signature }]);
  });

  it('fails closed on forged projections and malformed or unbounded trajectory data', () => {
    const signature = buildNativeRepairSignatureFromEvidence(evidenceInput()).signatureHash;
    const firstWarn = repairEvent(1, {
      signatureHash: signature,
      disposition: 'warn',
      overrideSummaryHash: null,
    });
    expect(() => rebuildNativeRepairHistory(committed([firstWarn]))).toThrow('expected continue');

    const wrongTransition = event(1, {
      previousPhase: 'build',
      nextPhase: 'verify',
      verificationResult: null,
      [NATIVE_REPAIR_TRAJECTORY_FIELD]: {
        signatureHash: signature,
        disposition: 'continue',
        overrideSummaryHash: null,
      },
    });
    expect(() => rebuildNativeRepairHistory(committed([wrongTransition]))).toThrow(
      'failed Verify-to-Build',
    );

    const forgedOverride = overrideEvent(1, {
      signatureHash: signature,
      disposition: 'continue',
      overrideSummaryHash: 'd'.repeat(64),
    });
    expect(() => rebuildNativeRepairHistory(committed([forgedOverride]))).toThrow(
      'latest manual stop',
    );

    expect(() =>
      parseNativeRepairTrajectoryProjection({
        signatureHash: signature,
        disposition: 'manual-stop',
        overrideSummaryHash: null,
        output: 'must never be persisted',
      }),
    ).toThrow('fields are invalid');

    const unknownOuterField = event(
      1,
      {},
      {
        forged: true,
      },
    );
    expect(() => rebuildNativeRepairHistory(committed([unknownOuterField]))).toThrow(
      'fields are invalid',
    );

    const cycle: Record<string, unknown> = {};
    cycle.self = cycle;
    expect(() => rebuildNativeRepairHistory(committed([event(1, cycle)]))).toThrow('cycle');

    const tooMany = Array.from(
      { length: NATIVE_REPAIR_TRAJECTORY_LIMITS.maxEvents + 1 },
      () => null,
    );
    expect(() => rebuildNativeRepairHistory(committed(tooMany))).toThrow('event boundary');
  });

  it('rejects pass evidence and content authorities that do not match the envelope', () => {
    const evidence = evidenceInput();
    expect(() => nativeRepairFailureFacts(evidenceInput('pass'))).toThrow(
      'requires a failed verification envelope',
    );

    const different = evidenceInput('fail', 'd'.repeat(64));
    expect(() =>
      nativeRepairFailureFacts({
        envelope: evidence.envelope,
        implementationScope: different.implementationScope,
      }),
    ).toThrow('does not match');

    const forgedScope = structuredClone(evidence.implementationScope);
    forgedScope.scope.scopeHash = 'f'.repeat(64);
    expect(() =>
      nativeRepairFailureFacts({ envelope: evidence.envelope, implementationScope: forgedScope }),
    ).toThrow();
  });
});

import { describe, expect, it } from 'vitest';

import {
  buildNativeRepairSignature,
  decideNativeRepairOverride,
  decideNativeRepairStagnation,
  hashNativeRepairOverrideSummary,
  type NativeRepairFailureFacts,
  type NativeRepairHistoryRecord,
} from '../../../domains/comet-native/native-repair-stagnation.js';

const A = 'a'.repeat(64);
const B = 'b'.repeat(64);
const C = 'c'.repeat(64);

function facts(overrides: Partial<NativeRepairFailureFacts> = {}): NativeRepairFailureFacts {
  return {
    contractHash: A,
    implementationScopeHash: B,
    artifactSnapshotHash: C,
    categories: ['test-failure'],
    failedAcceptanceIds: [`acceptance-${A}`],
    failedCheckIds: ['auth.invalid', 'auth.valid'],
    ...overrides,
  };
}

function failures(signatureHash: string, count: number): NativeRepairHistoryRecord[] {
  return Array.from({ length: count }, (_, index) => ({
    kind: 'failure' as const,
    revision: index + 1,
    iteration: index + 1,
    signatureHash,
  }));
}

describe('Native repair stagnation control', () => {
  it('normalizes failure facts without depending on category or check order', () => {
    const first = buildNativeRepairSignature(facts());
    const reordered = buildNativeRepairSignature({
      ...facts(),
      categories: ['test-failure'],
      failedCheckIds: ['auth.valid', 'auth.invalid'],
    });

    expect(reordered).toEqual(first);
    expect(first.signatureHash).toMatch(/^[a-f0-9]{64}$/u);
  });

  it('continues once, warns on the first repeat, and stops on the third identical failure', () => {
    const signature = buildNativeRepairSignature(facts());
    expect(
      decideNativeRepairStagnation({
        facts: facts(),
        history: [],
        maxVerifyFailures: 5,
      }),
    ).toMatchObject({
      disposition: 'continue',
      consecutiveFailures: 1,
    });
    expect(
      decideNativeRepairStagnation({
        facts: facts(),
        history: failures(signature.signatureHash, 1),
        maxVerifyFailures: 5,
      }),
    ).toMatchObject({ disposition: 'warn', consecutiveFailures: 2 });
    expect(
      decideNativeRepairStagnation({
        facts: facts(),
        history: failures(signature.signatureHash, 2),
        maxVerifyFailures: 5,
      }),
    ).toMatchObject({ disposition: 'manual-stop', consecutiveFailures: 3 });
  });

  it('ignores implementation churn but treats a changed semantic gap as progress', () => {
    const original = buildNativeRepairSignature(facts());
    const scopeOnly = decideNativeRepairStagnation({
      facts: facts({ artifactSnapshotHash: A, implementationScopeHash: C }),
      history: failures(original.signatureHash, 1),
      maxVerifyFailures: 5,
    });
    expect(scopeOnly).toMatchObject({
      disposition: 'warn',
      consecutiveFailures: 2,
    });

    const changedGap = decideNativeRepairStagnation({
      facts: facts({ artifactSnapshotHash: A, failedCheckIds: ['auth.valid'] }),
      history: failures(original.signatureHash, 2),
      maxVerifyFailures: 5,
    });

    expect(changedGap).toMatchObject({
      disposition: 'continue',
      reasonCode: 'new-failure-signature',
      consecutiveFailures: 1,
    });
  });

  it('resets stagnation only for a strict semantic gap reduction', () => {
    const previousFacts = facts({
      failedAcceptanceIds: [`acceptance-${A}`, `acceptance-${B}`],
      failedCheckIds: ['check-a', 'check-b'],
    });
    const previous = buildNativeRepairSignature(previousFacts);
    const history: NativeRepairHistoryRecord[] = [1, 2].map((iteration) => ({
      kind: 'failure',
      revision: iteration,
      iteration,
      signatureHash: previous.signatureHash,
      failedAcceptanceIds: [...previous.failedAcceptanceIds],
      failedCheckIds: [...previous.failedCheckIds],
    }));
    const swappedFacts = facts({
      failedAcceptanceIds: [`acceptance-${A}`, `acceptance-${C}`],
      failedCheckIds: ['check-a', 'check-c'],
    });
    expect(
      decideNativeRepairStagnation({
        facts: swappedFacts,
        history,
        maxVerifyFailures: 5,
      }),
    ).toMatchObject({ disposition: 'manual-stop', consecutiveFailures: 3 });

    const reducedFacts = facts({
      failedAcceptanceIds: [`acceptance-${A}`],
      failedCheckIds: ['check-a'],
    });
    expect(
      decideNativeRepairStagnation({
        facts: reducedFacts,
        history,
        maxVerifyFailures: 5,
      }),
    ).toMatchObject({ disposition: 'continue', consecutiveFailures: 1 });
  });

  it('allows one explicit matching override but never a second one', () => {
    const signature = buildNativeRepairSignature(facts());
    const history = failures(signature.signatureHash, 2);
    const first = decideNativeRepairStagnation({
      facts: facts(),
      history,
      maxVerifyFailures: 5,
      override: {
        expectedSignatureHash: signature.signatureHash,
        summary: 'Try the independent compatibility path once.',
      },
    });
    expect(first).toMatchObject({
      disposition: 'continue',
      reasonCode: 'override-accepted',
      overrideAccepted: true,
    });

    const second = decideNativeRepairStagnation({
      facts: facts(),
      history: [
        ...history,
        {
          kind: 'override',
          revision: 3,
          iteration: 3,
          signatureHash: signature.signatureHash,
          summaryHash: A,
        },
      ],
      maxVerifyFailures: 5,
      override: {
        expectedSignatureHash: signature.signatureHash,
        summary: 'Try again.',
      },
    });
    expect(second).toMatchObject({
      disposition: 'manual-stop',
      reasonCode: 'override-already-used',
      overrideAccepted: false,
    });
  });

  it('accepts an override on a later transition without counting the stopped failure twice', () => {
    const signature = buildNativeRepairSignature(facts());
    const stopped = failures(signature.signatureHash, 3);
    const accepted = decideNativeRepairOverride({
      facts: facts(),
      history: stopped,
      maxVerifyFailures: 5,
      override: {
        expectedSignatureHash: signature.signatureHash,
        summary: 'Try the independent path once.',
      },
    });
    expect(accepted).toMatchObject({
      disposition: 'continue',
      totalRepairFailures: 3,
      consecutiveFailures: 3,
      overrideAccepted: true,
    });

    expect(
      decideNativeRepairOverride({
        facts: facts(),
        history: [
          ...stopped,
          {
            kind: 'override',
            revision: 4,
            iteration: 3,
            signatureHash: signature.signatureHash,
            summaryHash: hashNativeRepairOverrideSummary('Try the independent path once.'),
          },
        ],
        maxVerifyFailures: 5,
        override: {
          expectedSignatureHash: signature.signatureHash,
          summary: 'A second attempt must be refused.',
        },
      }),
    ).toMatchObject({ reasonCode: 'override-already-used', overrideAccepted: false });
  });

  it('hard-stops at the total iteration ceiling even when the signature changed', () => {
    const old = buildNativeRepairSignature(facts({ contractHash: B }));
    const result = decideNativeRepairStagnation({
      facts: facts(),
      history: failures(old.signatureHash, 4),
      maxVerifyFailures: 5,
      override: {
        expectedSignatureHash: buildNativeRepairSignature(facts()).signatureHash,
        summary: 'The limit must still win.',
      },
    });

    expect(result).toMatchObject({
      disposition: 'hard-stop',
      reasonCode: 'repair-iteration-limit',
      remainingIterations: 0,
      overrideAccepted: false,
    });
  });

  it('fails closed on malformed IDs, duplicate history ordering, and mismatched override', () => {
    expect(() => buildNativeRepairSignature(facts({ failedCheckIds: ['bad check'] }))).toThrow(
      'invalid token',
    );
    const signature = buildNativeRepairSignature(facts());
    expect(() =>
      decideNativeRepairStagnation({
        facts: facts(),
        history: [
          { kind: 'failure', revision: 2, iteration: 2, signatureHash: signature.signatureHash },
          { kind: 'failure', revision: 1, iteration: 1, signatureHash: signature.signatureHash },
        ],
        maxVerifyFailures: 5,
      }),
    ).toThrow('strictly ordered');
    expect(() =>
      decideNativeRepairStagnation({
        facts: facts(),
        history: failures(signature.signatureHash, 2),
        maxVerifyFailures: 5,
        override: { expectedSignatureHash: B, summary: 'Wrong failure.' },
      }),
    ).toThrow('does not match');
    expect(() =>
      decideNativeRepairStagnation({
        facts: facts(),
        history: [
          {
            kind: 'failure',
            revision: 1,
            iteration: 1,
            signatureHash: signature.signatureHash,
            forged: true,
          } as unknown as NativeRepairHistoryRecord,
        ],
        maxVerifyFailures: 5,
      }),
    ).toThrow('fields are invalid');
  });
});

