async function registration(
  phase: 'running' | 'interrupted' | 'completed',
  modern = false,
  retainLease = false,
) {
  const action = {
    id: 'check-action',
    runId: 'check-run',
    attempt: 1,
    inputHash: 'original-input',
    type: 'call_tool',
    ref: 'native-required-checks',
    status: 'unknown',
    claim: { token: 'original-claim', executorId: 'comet-native-checks' },
  } as RuntimeAction;
  const run = {
    runId: 'check-run',
    workflow: { id: 'comet-native', version: '1', hash: 'a'.repeat(64) },
    actions: [action],
  } as WorkflowRun;
  const registered = await createNativeSdkCheckExecution({
    projectRoot: root,
    run,
    action,
    candidateId: 'original-candidate',
    plansHash: 'original-plans',
  });
  await registered.register('check-1', modern ? instance : { instanceId: 'legacy-instance' });
  registered.execution.phase = phase;
  await registered.save();
  if (!retainLease) await registered.release();
  return { run, action, registered };
}

