    ).toThrow('exceptional selection');
    expect(
      parseNativeContentSnapshotManifest({
        ...base,
        capture: { provider: 'physical-tree', projection: { provider: 'git' } },
      }),
    ).toMatchObject({ capture: { provider: 'physical-tree', projection: { provider: 'git' } } });
