      const manifest = await createNativeContentSnapshot(paths);
      expect(readSpy).toBeDefined();
      expect(readSpy).not.toHaveBeenCalled();
      expect(manifest.entries).toEqual([]);
      expect(manifest.omitted).toEqual([
        {
