      },
      limits: {
        maxFileBytes: 2048,
        maxTotalBytes: 2048,
        maxDurationMs: 60_000,
      },
    });

    expect(manifest.complete).toBe(true);
    expect(manifest.entries.map((entry) => entry.path)).toEqual(['src/app.ts']);
    expect(manifest.omitted).toEqual([]);
    expect(manifest.policy).toMatchObject({
