  it('matches snapshot globs without catastrophic backtracking', () => {
    const matcher = compileNativeSnapshotPattern(`${'**/'.repeat(8)}target.ts`);
    const startedAt = performance.now();

    expect(matcher(`${'nested/'.repeat(80)}missing.ts`)).toBe(false);
    expect(performance.now() - startedAt).toBeLessThan(100);
  });

  it('stops snapshot glob matching cooperatively when its budget expires', () => {
    const matcher = compileNativeSnapshotPattern('**') as (
      relative: string,
      hasBudget?: () => boolean,
    ) => boolean;
    let budgetChecks = 0;

    expect(
      matcher('x'.repeat(4_096), () => {
        budgetChecks += 1;
        return budgetChecks === 1;
      }),
    ).toBe(false);
    expect(budgetChecks).toBeGreaterThan(1);
  });

  it.each([
    ['src/**/*.ts', 'src/index.ts', true],
    ['src/**/*.ts', 'src/nested/index.ts', true],
    ['src/**/*.ts', 'src/nested/index.js', false],
    ['assets/**', 'assets/icons/logo.svg', true],
    ['?.md', 'a.md', true],
    ['?.md', 'docs/a.md', false],
  ])('matches snapshot glob %s against %s', (pattern, relativePath, expected) => {
    expect(compileNativeSnapshotPattern(pattern)(relativePath)).toBe(expected);
  });

  it('covers literal, wildcard, slash-sensitive, and invalid snapshot patterns', () => {
    const cases: Array<[string, string, boolean]> = [
      ['src/file.ts', 'src/file.ts', true],
      ['src/file.ts', 'src/other.ts', false],
      ['src/?.ts', 'src/a.ts', true],
      ['src/?.ts', 'src/.ts', false],
      ['src/?.ts', 'src/a/b.ts', false],
      ['src/*.ts', 'src/file.ts', true],
      ['src/*.ts', 'src/nested/file.ts', false],
      ['**/*.ts', 'file.ts', true],
      ['**/*.ts', 'src/nested/file.ts', true],
      ['src/**', 'src/nested/file.ts', true],
      ['src/**', 'other/file.ts', false],
      ['**', 'a/b/c.ts', true],
    ];
    for (const [pattern, value, expected] of cases) {
      expect(compileNativeSnapshotPattern(pattern)(value), `${pattern} -> ${value}`).toBe(expected);
    }
    expect(compileNativeSnapshotPattern('**/*')('src/file.ts', () => false)).toBe(false);
    for (const pattern of ['', '../outside', 'a\\b', 'a\0b']) {
      expect(() => compileNativeSnapshotPattern(pattern)).toThrow();
    }
  });

  it('retains a deterministic hash/ref for omissions beyond the recorded output budget', async () => {
    await Promise.all(
      Array.from({ length: 1_003 }, (_, index) =>
        fs.writeFile(
          path.join(projectRoot, `overflow-${index.toString().padStart(4, '0')}.txt`),
          'x',
        ),
      ),
    );
    const options = {
      limits: { maxFiles: 1, maxFileBytes: 1, maxTotalBytes: 1 },
    } as const;

    const first = await createNativeContentSnapshot(paths, options);
    const second = await createNativeContentSnapshot(paths, options);

    expect(first.omittedCount).toBe(1_002);
    expect(first.omitted).toHaveLength(1_000);
    expect(first.omissionOverflow).toMatchObject({
      count: 2,
      hash: expect.stringMatching(/^[a-f0-9]{64}$/u),
      ref: expect.stringMatching(/^native-snapshot:\/\/omitted-overflow\/[a-f0-9]{64}$/u),
    });
    expect(second.omissionOverflow).toEqual(first.omissionOverflow);
    const serialized = JSON.stringify(first);
    expect(serialized).not.toContain('overflow-1001.txt');
    expect(serialized).not.toContain('overflow-1002.txt');
  });

  it('keeps every entry regardless of the serialized manifest size', async () => {
    const files = Array.from({ length: 40 }, (_, index) =>
      path.join(
        projectRoot,
        `manifest-${index.toString().padStart(2, '0')}-${'x'.repeat(120)}.txt`,
      ),
    );
    await Promise.all(files.map((file) => fs.writeFile(file, 'x')));
    const options = {
      now: new Date('2026-07-17T00:00:00.000Z'),
      limits: { maxManifestBytes: 1_500 },
    } as const;
    const manifest = await createNativeContentSnapshot(paths, options);
    const serialized = JSON.stringify(manifest, null, 2) + '\n';

    expect(Buffer.byteLength(serialized)).toBeGreaterThan(1_500);
    expect(manifest.complete).toBe(true);
    expect(manifest.entries).toHaveLength(files.length);
    expect(manifest.omitted).toEqual([]);
    expect(parseNativeContentSnapshotManifest(JSON.parse(serialized))).toEqual(manifest);
  });

  it('removes a newly created change directory when baseline capture fails so retry can succeed', async () => {
    const originalOpendir = fs.opendir.bind(fs);
    let failProjectRead = true;
    const spy = vi.spyOn(fs, 'opendir').mockImplementation(async (...args) => {
      if (failProjectRead && path.resolve(String(args[0])) === path.resolve(projectRoot)) {
        throw Object.assign(new Error('permission denied'), { code: 'EACCES' });
      }
      return originalOpendir(...args);
    });
    try {
      await expect(
        createNativeChange({
          paths,
          name: 'retryable-change',
          language: 'en',
          verificationProtocol: 'legacy-v1',
        }),
      ).rejects.toMatchObject({ code: 'EACCES' });
      await expect(fs.access(nativeChangeDir(paths, 'retryable-change'))).rejects.toMatchObject({
        code: 'ENOENT',
      });

      failProjectRead = false;
      await expect(
        createNativeChange({
          paths,
          name: 'retryable-change',
          language: 'en',
          verificationProtocol: 'legacy-v1',
        }),
      ).resolves.toMatchObject({ name: 'retryable-change', revision: 1 });
    } finally {
      spy.mockRestore();
    }
  });
});

describe('Native incremental content snapshots', () => {
  let projectRoot: string;
  let paths: NativeProjectPaths;

  beforeEach(async () => {
    projectRoot = await fs.mkdtemp(path.join(os.tmpdir(), 'comet-native-incremental-'));
    paths = await nativeProjectPaths(projectRoot, '.');
    await fs.mkdir(paths.nativeRoot, { recursive: true });
  });

  afterEach(async () => {
    await fs.rm(projectRoot, { recursive: true, force: true, maxRetries: 5 });
  });

  async function initGitRepo(): Promise<void> {
    await execFileAsync('git', ['init'], { cwd: projectRoot });
    await execFileAsync('git', ['config', 'user.email', 'test@example.com'], { cwd: projectRoot });
    await execFileAsync('git', ['config', 'user.name', 'Test'], { cwd: projectRoot });
  }

  /**
   * Compute the projection hash from a manifest — the value that receipts
   * bind to. Incremental and full snapshots must produce the same hash when
   * the file tree is unchanged.
   */
  function projectionHashOf(
    manifest: Parameters<typeof buildNativeImplementationScopeBundle>[0]['current'],
  ): string {
    const bundle = buildNativeImplementationScopeBundle({
      baseline: manifest,
      current: manifest,
      contractHash: '0'.repeat(64),
      declaredArtifacts: [],
      noCodeReason: null,
    });
    return bundle.scope.currentProjectionHash;
  }

  /**
   * Produce a full (non-incremental) snapshot using the same config-derived
   * limits as `createNativeCurrentContentSnapshot`, so the only difference
   * from the incremental call is the reuse of baseline hashes. Both calls
   * pass a baseline manifest for policy, but only `incremental` passes one
   * whose entries carry gitObjectId (enabling the incremental path).
   */
  async function fullCurrentSnapshot(
    baseline: Awaited<ReturnType<typeof createNativeContentSnapshot>>,
  ): Promise<NativeContentSnapshotManifest> {
    // Strip gitObjectId so the incremental path stays disabled (full capture).
    const legacyPolicyBaseline = parseNativeContentSnapshotManifest({
      ...baseline,
      entries: baseline.entries.map((entry) => {
        const { gitObjectId: _removed, ...rest } = entry;
        return rest;
      }),
    });
    return createNativeCurrentContentSnapshot(paths, legacyPolicyBaseline);
  }

  it.each([false, true])(
    'rejects a file replaced after metadata prefetch (incremental: %s)',
    async (incremental) => {
      await initGitRepo();
      const refs = ['a.ts', 'b.ts', 'c.ts', 'd.ts'];
      await Promise.all(refs.map((ref) => fs.writeFile(path.join(projectRoot, ref), ref)));
      await execFileAsync('git', ['add', '-A'], { cwd: projectRoot });
      const baseline = await createNativeContentSnapshot(paths);
      const lstat = fs.lstat.bind(fs);
      let observedB!: () => void;
      const bReady = new Promise<void>((resolve) => {
        observedB = resolve;
      });
      let replaced = false;
      const spy = vi.spyOn(fs, 'lstat').mockImplementation(async (...args) => {
        const stat = await lstat(...args);
        if (String(args[0]) === path.join(projectRoot, 'b.ts')) observedB();
        if (String(args[0]) === path.join(projectRoot, 'd.ts') && !replaced) {
          await bReady;
          replaced = true;
          await fs.unlink(path.join(projectRoot, 'b.ts'));
          await fs.writeFile(path.join(projectRoot, 'b.ts'), 'replacement content');
        }
        return stat;
      });
      try {
        const snapshot = await createNativeContentSnapshot(paths, {
          ...(incremental ? { incrementalBaseline: baseline } : {}),
        });
        expect(replaced).toBe(true);
        expect(snapshot.complete).toBe(false);
        expect(snapshot.entries.some((entry) => entry.path === 'b.ts')).toBe(false);
        expect(snapshot.omitted).toContainEqual(
          expect.objectContaining({
            path: 'b.ts',
            reason: 'changed-during-read',
          }),
        );
      } finally {
        spy.mockRestore();
      }
    },
  );

  it.runIf(process.platform !== 'win32').each([
    { incremental: false, destination: 'outside' },
    { incremental: true, destination: 'outside' },
    { incremental: false, destination: 'native' },
    { incremental: true, destination: 'native' },
  ])(
    'rejects a prefetched file replaced by a $destination symlink (incremental: $incremental)',
    async ({ incremental, destination }) => {
      await initGitRepo();
      const refs = ['a.ts', 'b.ts', 'c.ts', 'd.ts'];
      await Promise.all(refs.map((ref) => fs.writeFile(path.join(projectRoot, ref), ref)));
      await execFileAsync('git', ['add', '-A'], { cwd: projectRoot });
      const baseline = await createNativeContentSnapshot(paths);
      const outside = await fs.mkdtemp(path.join(os.tmpdir(), 'comet-snapshot-link-'));
      const excludedFile = path.join(
        destination === 'outside' ? outside : paths.nativeRoot,
        'secret.txt',
      );
      await fs.writeFile(excludedFile, 'must never be opened');
      const lstat = fs.lstat.bind(fs);
      let observedB!: () => void;
      const bReady = new Promise<void>((resolve) => {
        observedB = resolve;
      });
      let replaced = false;
      const spy = vi.spyOn(fs, 'lstat').mockImplementation(async (...args) => {
        const stat = await lstat(...args);
        if (String(args[0]) === path.join(projectRoot, 'b.ts')) observedB();
        if (String(args[0]) === path.join(projectRoot, 'd.ts') && !replaced) {
          await bReady;
          replaced = true;
          await fs.unlink(path.join(projectRoot, 'b.ts'));
          await fs.symlink(excludedFile, path.join(projectRoot, 'b.ts'), 'file');
        }
        return stat;
      });
      const openSpy = vi.spyOn(fs, 'open');
      try {
        const snapshot = await createNativeContentSnapshot(paths, {
          ...(incremental ? { incrementalBaseline: baseline } : {}),
        });
        expect(replaced).toBe(true);
        expect(snapshot.complete).toBe(false);
        expect(snapshot.entries.map((entry) => entry.path)).toEqual(['a.ts', 'c.ts', 'd.ts']);
        expect(snapshot.omitted).toContainEqual(
          expect.objectContaining({
            path: 'b.ts',
            reason: 'changed-during-read',
          }),
        );
        expect(
          openSpy.mock.calls.some(([file]) =>
            [excludedFile, path.join(projectRoot, 'b.ts')].includes(String(file)),
          ),
        ).toBe(false);
      } finally {
        spy.mockRestore();
        openSpy.mockRestore();
        await fs.rm(outside, { recursive: true, force: true });
      }
    },
  );

  it.runIf(process.platform !== 'win32').each(['outside', 'native'])(
    'preserves stable excluded directory aliases into %s paths',
    async (destination) => {
      await initGitRepo();
      const alias = path.join(projectRoot, 'alias');
      await fs.mkdir(alias);
      await fs.writeFile(path.join(alias, 'file.ts'), 'tracked file');
      await fs.writeFile(path.join(projectRoot, 'a.ts'), 'included');
      await execFileAsync('git', ['add', '-A'], { cwd: projectRoot });
      const outside = await fs.mkdtemp(path.join(os.tmpdir(), 'comet-snapshot-alias-'));
      const excludedRoot = destination === 'outside' ? outside : paths.nativeRoot;
      await fs.writeFile(path.join(excludedRoot, 'file.ts'), 'excluded content');
      await fs.rm(alias, { recursive: true });
      await fs.symlink(excludedRoot, alias, 'dir');
      const openSpy = vi.spyOn(fs, 'open');
      try {
        const snapshot = await createNativeContentSnapshot(paths);
        expect(snapshot.complete).toBe(true);
        expect(snapshot.entries.some((entry) => entry.path === 'alias/file.ts')).toBe(false);
        expect(snapshot.entries.some((entry) => entry.path === 'a.ts')).toBe(true);
        expect(snapshot.omitted).toEqual([]);
        expect(openSpy.mock.calls.some(([file]) => String(file).endsWith('file.ts'))).toBe(false);
      } finally {
        openSpy.mockRestore();
        await fs.rm(outside, { recursive: true, force: true });
      }
    },
  );

  it('preloads clean tracked metadata with bounded concurrency and no content reads', async () => {
    await initGitRepo();
    const refs = Array.from(
      { length: 24 },
      (_, index) => `file-${String(index).padStart(2, '0')}.ts`,
    );
    await Promise.all(refs.map((ref) => fs.writeFile(path.join(projectRoot, ref), ref)));
    await execFileAsync('git', ['add', '-A'], { cwd: projectRoot });
    const baseline = await createNativeContentSnapshot(paths);
    const lstat = fs.lstat.bind(fs);
    let active = 0;
    let peak = 0;
    const statSpy = vi.spyOn(fs, 'lstat').mockImplementation(async (...args) => {
      if (!String(args[0]).endsWith('.ts')) return lstat(...args);
      active += 1;
      peak = Math.max(peak, active);
      try {
        await new Promise((resolve) => setTimeout(resolve, 5));
        return await lstat(...args);
      } finally {
        active -= 1;
      }
    });
    const openSpy = vi.spyOn(fs, 'open');
    try {
      const snapshot = await createNativeContentSnapshot(paths, { incrementalBaseline: baseline });
      expect(snapshot.complete).toBe(true);
      expect(snapshot.entries).toEqual(baseline.entries);
      expect(peak).toBeGreaterThan(1);
      expect(peak).toBeLessThanOrEqual(16);
      expect(active).toBe(0);
      expect(openSpy.mock.calls.some(([file]) => String(file).endsWith('.ts'))).toBe(false);
      const limited = await createNativeContentSnapshot(paths, {
        incrementalBaseline: baseline,
        limits: { maxFiles: 3 },
      });
      expect(limited.entries.map((entry) => entry.path)).toEqual(refs.slice(0, 3));
      expect(limited.omittedCount).toBe(21);
      expect(active).toBe(0);
    } finally {
      statSpy.mockRestore();
      openSpy.mockRestore();
    }
  });

  it('produces an identical projection hash when no files changed since baseline', async () => {
    await initGitRepo();
    await fs.writeFile(path.join(projectRoot, 'a.ts'), 'export const a = 1;\n');
    await fs.writeFile(path.join(projectRoot, 'b.ts'), 'export const b = 2;\n');
    await execFileAsync('git', ['add', '-A'], { cwd: projectRoot });
    await execFileAsync('git', ['commit', '-m', 'init'], { cwd: projectRoot });

    const baseline = await createNativeContentSnapshot(paths);
    expect(baseline.entries.every((e) => e.gitObjectId !== undefined)).toBe(true);

    const full = await fullCurrentSnapshot(baseline);
    const incremental = await createNativeCurrentContentSnapshot(paths, baseline);

    expect(projectionHashOf(incremental)).toBe(projectionHashOf(full));
    expect(incremental.entries).toHaveLength(full.entries.length);
  });

  it('re-captures a working-tree-modified file instead of reusing the stale hash', async () => {
    await initGitRepo();
    await fs.writeFile(path.join(projectRoot, 'a.ts'), 'export const a = 1;\n');
    await execFileAsync('git', ['add', '-A'], { cwd: projectRoot });
    await execFileAsync('git', ['commit', '-m', 'init'], { cwd: projectRoot });

    const baseline = await createNativeContentSnapshot(paths);

    // Modify the file in the working tree WITHOUT staging — git index object
    // id is unchanged, but content differs. The incremental path must detect
    // this via `git ls-files --modified` and re-hash from disk.
    await fs.writeFile(path.join(projectRoot, 'a.ts'), 'export const a = 999;\n');

    const full = await fullCurrentSnapshot(baseline);
    const incremental = await createNativeCurrentContentSnapshot(paths, baseline);

    // Both must reflect the actual disk content, not the stale baseline hash.
    expect(projectionHashOf(incremental)).toBe(projectionHashOf(full));
    expect(incremental.entries[0]!.hash).toBe(full.entries[0]!.hash);
    expect(incremental.entries[0]!.hash).not.toBe(baseline.entries[0]!.hash);
  });

  it('re-captures index-hidden files that Git omits from the modified set', async () => {
    await initGitRepo();
    await fs.writeFile(path.join(projectRoot, 'a.ts'), 'export const a = 1;\n');
    await fs.writeFile(path.join(projectRoot, 'b.ts'), 'export const b = 1;\n');
    await execFileAsync('git', ['add', '-A'], { cwd: projectRoot });
    await execFileAsync('git', ['commit', '-m', 'init'], { cwd: projectRoot });

    const baseline = await createNativeContentSnapshot(paths);
    await execFileAsync('git', ['update-index', '--assume-unchanged', 'a.ts'], {
      cwd: projectRoot,
    });
    await execFileAsync('git', ['update-index', '--skip-worktree', 'b.ts'], {
      cwd: projectRoot,
    });
    await fs.writeFile(path.join(projectRoot, 'a.ts'), 'export const a = 2;\n');
    await fs.writeFile(path.join(projectRoot, 'b.ts'), 'export const b = 2;\n');
    const { stdout: modified } = await execFileAsync('git', ['ls-files', '--modified'], {
      cwd: projectRoot,
    });
    expect(modified).toBe('');

    const full = await fullCurrentSnapshot(baseline);
    const incremental = await createNativeCurrentContentSnapshot(paths, baseline);
    expect(projectionHashOf(incremental)).toBe(projectionHashOf(full));
    expect(incremental.entries.map((entry) => entry.hash)).not.toEqual(
      baseline.entries.map((entry) => entry.hash),
    );
    expect(incremental.entries.every((entry) => entry.gitObjectId === undefined)).toBe(true);
  });

  it('captures newly added files that were not in baseline', async () => {
    await initGitRepo();
    await fs.writeFile(path.join(projectRoot, 'a.ts'), 'export const a = 1;\n');
    await execFileAsync('git', ['add', '-A'], { cwd: projectRoot });
    await execFileAsync('git', ['commit', '-m', 'init'], { cwd: projectRoot });

    const baseline = await createNativeContentSnapshot(paths);

    // Add a new tracked file.
    await fs.writeFile(path.join(projectRoot, 'b.ts'), 'export const b = 2;\n');
    await execFileAsync('git', ['add', '-A'], { cwd: projectRoot });
    await execFileAsync('git', ['commit', '-m', 'add b'], { cwd: projectRoot });

    const full = await fullCurrentSnapshot(baseline);
    const incremental = await createNativeCurrentContentSnapshot(paths, baseline);

    expect(projectionHashOf(incremental)).toBe(projectionHashOf(full));
    expect(incremental.entries.map((e) => e.path).sort()).toEqual(['a.ts', 'b.ts']);
  });

  it('falls back to full capture when baseline entries lack gitObjectId', async () => {
    await initGitRepo();
    await fs.writeFile(path.join(projectRoot, 'a.ts'), 'export const a = 1;\n');
    await execFileAsync('git', ['add', '-A'], { cwd: projectRoot });
    await execFileAsync('git', ['commit', '-m', 'init'], { cwd: projectRoot });

    const realBaseline = await createNativeContentSnapshot(paths);
    // Simulate a legacy manifest by stripping gitObjectId from every entry.
    const legacyBaseline = parseNativeContentSnapshotManifest({
      ...realBaseline,
      entries: realBaseline.entries.map((entry) => {
        const { gitObjectId: _removed, ...rest } = entry;
        return rest;
      }),
    });
    expect(legacyBaseline.entries.every((e) => e.gitObjectId === undefined)).toBe(true);

    const full = await fullCurrentSnapshot(realBaseline);
    // Passing a legacy baseline must not break — it degrades to full capture.
    const result = await createNativeCurrentContentSnapshot(paths, legacyBaseline);
    expect(projectionHashOf(result)).toBe(projectionHashOf(full));
  });

  it('does not bind a working-tree hash to the index object id', async () => {
    await initGitRepo();
    await fs.writeFile(path.join(projectRoot, 'a.ts'), 'base\n');
    await execFileAsync('git', ['add', '-A'], { cwd: projectRoot });
    await execFileAsync('git', ['commit', '-m', 'init'], { cwd: projectRoot });

    await fs.writeFile(path.join(projectRoot, 'a.ts'), 'modified\n');
    const dirtyBaseline = await createNativeContentSnapshot(paths);
    expect(dirtyBaseline.entries[0]!.gitObjectId).toBeUndefined();

    await execFileAsync('git', ['restore', 'a.ts'], { cwd: projectRoot });
    const incremental = await createNativeContentSnapshot(paths, {
      policy: dirtyBaseline.policy,
      incrementalBaseline: dirtyBaseline,
    });
    const full = await createNativeContentSnapshot(paths, { policy: dirtyBaseline.policy });

    expect(incremental.entries).toEqual(full.entries);
    expect(projectionHashOf(incremental)).toBe(projectionHashOf(full));
  });

  it('reuses eligible tracked entries when another baseline entry has no gitObjectId', async () => {
    await initGitRepo();
    await fs.writeFile(path.join(projectRoot, 'a.ts'), 'tracked\n');
    await execFileAsync('git', ['add', '-A'], { cwd: projectRoot });
    await execFileAsync('git', ['commit', '-m', 'init'], { cwd: projectRoot });
    await fs.writeFile(path.join(projectRoot, 'z-untracked.txt'), 'untracked\n');

    const baseline = await createNativeContentSnapshot(paths);
    expect(baseline.entries.find((entry) => entry.path === 'a.ts')?.gitObjectId).toBeDefined();
    expect(
      baseline.entries.find((entry) => entry.path === 'z-untracked.txt')?.gitObjectId,
    ).toBeUndefined();

    const captured: string[] = [];
    const incremental = await createNativeContentSnapshot(paths, {
      policy: baseline.policy,
      incrementalBaseline: baseline,
      gitSelectionHooks: {
        afterFirstEntryCaptured: (relative) => {
          captured.push(relative);
        },
      },
    });

    expect(captured).toEqual(['z-untracked.txt']);
    expect(projectionHashOf(incremental)).toBe(projectionHashOf(baseline));
  });

  it('invalidates a reused entry modified after the initial worktree fence', async () => {
    await initGitRepo();
    await fs.writeFile(path.join(projectRoot, 'a.ts'), 'a0\n');
    await fs.writeFile(path.join(projectRoot, 'b.ts'), 'b0\n');
    await execFileAsync('git', ['add', '-A'], { cwd: projectRoot });
    await execFileAsync('git', ['commit', '-m', 'init'], { cwd: projectRoot });

    const baseline = await createNativeContentSnapshot(paths);
    await fs.writeFile(path.join(projectRoot, 'a.ts'), 'a1\n');
    let changed = false;
    const incremental = await createNativeContentSnapshot(paths, {
      policy: baseline.policy,
      incrementalBaseline: baseline,
      gitSelectionHooks: {
        afterFirstEntryCaptured: async (relative) => {
          if (relative === 'a.ts') {
            changed = true;
            await fs.writeFile(path.join(projectRoot, 'b.ts'), 'b1\n');
          }
        },
      },
    });

    expect(changed).toBe(true);
    expect(incremental.entries.some((entry) => entry.path === 'b.ts')).toBe(false);
    expect(incremental.omitted).toContainEqual({
      path: 'b.ts',
      size: 3,
      type: 'file',
      reason: 'changed-during-read',
    });
    expect(incremental.complete).toBe(false);
  });

  it('drops a newly bound Git object id when the file becomes modified after capture', async () => {
    await initGitRepo();
    await fs.writeFile(path.join(projectRoot, 'a.ts'), 'base\n');
    await execFileAsync('git', ['add', '-A'], { cwd: projectRoot });
    await execFileAsync('git', ['commit', '-m', 'init'], { cwd: projectRoot });

    const baseline = await createNativeContentSnapshot(paths);
    await fs.writeFile(path.join(projectRoot, 'a.ts'), 'staged\n');
    await execFileAsync('git', ['add', 'a.ts'], { cwd: projectRoot });

    const incremental = await createNativeContentSnapshot(paths, {
      policy: baseline.policy,
      incrementalBaseline: baseline,
      gitSelectionHooks: {
        afterContentRevalidation: async () => {
          await fs.writeFile(path.join(projectRoot, 'a.ts'), 'modified after capture\n');
        },
      },
    });

    const entry = incremental.entries.find((candidate) => candidate.path === 'a.ts');
    expect(entry).toEqual(expect.objectContaining({ path: 'a.ts', hash: sha256Text('staged\n') }));
    expect(entry).not.toHaveProperty('gitObjectId');
  });
});

import { promises as fs } from 'node:fs';
import { execFileSync } from 'node:child_process';
import os from 'node:os';
import path from 'node:path';
import { afterEach, describe, expect, it, vi } from 'vitest';
import * as checkExecutor from '../../../domains/comet-native/native-check-executor.js';
import * as atomicFile from '../../../domains/comet-native/native-atomic-file.js';
import { nativeDoctorCommand } from '../../../domains/comet-native/native-doctor-command.js';
import { inspectNativeCheckStopEvidenceTargets } from '../../../domains/comet-native/native-check-stop-evidence.js';
import {
  defaultProjectConfig,
  writeProjectConfig,
} from '../../../domains/comet-native/native-config.js';
import {
  ensureNativeDirectories,
  nativeProjectPaths,
} from '../../../domains/comet-native/native-paths.js';
import {
  createNativePortableChange,
  nativePortableChangeDir,
  prepareNativePortableShapeConfirmation,
  confirmNativePortableShape,
} from '../../../domains/comet-native/native-portable-runtime.js';
import { applyNativeRunnerInput } from '../../../domains/comet-native/native-runner-input.js';
import {
  dispatchNativeSupervisorReadyTasks,
  readNativeSupervisorState,
  writeNativeSupervisorState,
} from '../../../domains/comet-native/native-supervisor.js';
import { executeNativeSupervisorChecks } from '../../../domains/comet-native/native-supervisor-evidence.js';
import { withNativeMutationLock } from '../../../domains/comet-native/native-mutation-lock.js';

const roots: string[] = [];
afterEach(async () => {
  vi.restoreAllMocks();
  for (const root of roots.splice(0)) await fs.rm(root, { recursive: true, force: true });
});
const git = (cwd: string, ...args: string[]) =>
  execFileSync('git', args, { cwd, encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] }).trim();
const delay = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));

async function setup(secondChild = false) {
  const root = await fs.mkdtemp(path.join(os.tmpdir(), 'comet-supervisor-process-'));
  roots.push(root);
  git(root, 'init', '-b', 'main');
  git(root, 'config', 'user.email', 'test@example.test');
  git(root, 'config', 'user.name', 'Test');
  await writeProjectConfig(root, defaultProjectConfig('docs', 'en'));
  await fs.writeFile(
    path.join(root, '.gitignore'),
    '.comet/runtime/\n.comet/current-change.json\n.worktrees/\n',
  );
  git(root, 'add', '.');
  git(root, 'commit', '-m', 'seed');
  const paths = await nativeProjectPaths(root, 'docs');
  await ensureNativeDirectories(paths);
  await createNativePortableChange({
    paths,
    name: 'change',
    language: 'en',
    workspaceBinding: { isolation: 'current', changeBranch: 'main', targetBranch: 'main' },
  });
  const changeDir = nativePortableChangeDir(paths, 'change');
  await fs.writeFile(
    path.join(changeDir, 'brief.md'),
    '# Acceptance examples\n- The behavior works.\n' +
      (secondChild ? '- Another behavior works.\n' : ''),
  );
  await fs.writeFile(
    path.join(changeDir, 'children.yaml'),
    'schema: comet.native.children.v2\nacceptance_index:\n  A1:\n    source: brief.md\n    text: The behavior works.\n' +
      (secondChild ? '  A2:\n    source: brief.md\n    text: Another behavior works.\n' : '') +
      'children:\n  - name: core\n    depends_on: []\n    covers: [A1]\n' +
      (secondChild ? '  - name: auxiliary\n    depends_on: []\n    covers: [A2]\n' : ''),
  );
  const coordination = secondChild ? { coordinationMode: 'multi-session' as const } : {};
  await prepareNativePortableShapeConfirmation({ paths, name: 'change', ...coordination });
  await confirmNativePortableShape({ paths, name: 'change', ...coordination });
  const builders = (
    await dispatchNativeSupervisorReadyTasks({ paths, parent: 'change', maxParallel: 2 })
  ).tasks;
  const verifierRunIds: Record<string, string> = {};
  for (const builder of builders) {
    await fs.writeFile(path.join(builder.projectRoot, `${builder.child}.txt`), 'implemented');
    git(builder.projectRoot, 'add', `${builder.child}.txt`);
    git(builder.projectRoot, 'commit', '-m', 'implement');
    const result = await applyNativeRunnerInput({
      paths,
      name: 'change',
      maxVerifyFailures: 5,
      input: {
        kind: 'supervisor-builder-result',
        child: builder.child,
        runId: builder.runId,
        candidateCommit: git(builder.projectRoot, 'rev-parse', 'HEAD'),
      },
    });
    verifierRunIds[builder.child] = result.supervisorTask!.runId;
  }
  const marker = path.join(root, 'starts.txt');
  const release = path.join(root, 'release');
  const code =
    "require('fs').appendFileSync(process.argv[1],String(process.pid)+'\\n');setInterval(()=>{if(require('fs').existsSync(process.argv[2]))process.exit(0)},25)";
  const options = {
    paths,
    parent: 'change',
    child: 'core',
    runId: verifierRunIds.core,
    plans: [
      {
        id: 'slow',
        name: 'Slow check',
        executable: process.execPath,
        argv: ['-e', code, marker, release],
        cwdRef: '.',
        timeoutMs: 10000,
        repeatable: true,
      },
    ],
    materials: [],
  };
  return {
    root,
    paths,
    marker,
    release,
    options,
    secondaryOptions: { ...options, child: 'auxiliary', runId: verifierRunIds.auxiliary },
  };
}

describe('Supervisor check process recovery', () => {
  it('preserves unconfirmed process termination and blocks owner-dead recovery', async () => {
    const { paths, options, secondaryOptions } = await setup(true);
    const failure = new checkExecutor.NativeCheckTerminationUnconfirmedError();
    const execute = vi
      .spyOn(checkExecutor, 'executeNativeCheck')
      .mockImplementation(async ({ onSpawn }) => {
        await onSpawn?.({
          instanceId: 'original-check-instance',
          signal: new AbortController().signal,
        });
        throw failure;
      });
    await expect(executeNativeSupervisorChecks(options)).rejects.toBe(failure);
    await expect(executeNativeSupervisorChecks(secondaryOptions)).rejects.toBe(failure);
    const preserved = (await readNativeSupervisorState(paths, 'change'))!;
    const execution = preserved.children[0].task!.checkExecution!;
    expect(execution).toMatchObject({
      status: 'running',
      activeProcess: { status: 'running', checkId: 'slow', instanceId: 'original-check-instance' },
      checkStates: [{ id: 'slow', status: 'running', executionCount: 1 }],
    });
    await expect(
      executeNativeSupervisorChecks({ ...options, retryCheckIds: ['slow'] }),
    ).resolves.toMatchObject({ status: 'running', operationId: execution.operationId });

    execution.ownerPid = 2147483001;
    preserved.children[1].task!.checkExecution!.ownerPid = 2147483001;
    await writeNativeSupervisorState(paths, preserved);
    await expect(executeNativeSupervisorChecks(options)).resolves.toMatchObject({
      status: 'running',
      operationId: execution.operationId,
    });
    expect(
      (await readNativeSupervisorState(paths, 'change'))!.children[0].task!.checkExecution,
    ).toEqual(execution);
    expect(execute).toHaveBeenCalledTimes(2);

    const target = (await inspectNativeCheckStopEvidenceTargets(paths, 'change')).find(
      ({ child }) => child === 'core',
    )!;
    expect(target.canConfirm).toBe(true);
    const proofFile = path.join(paths.workspaceRuntimeRoot, 'supervisor-stopped.json');
    await fs.writeFile(
      proofFile,
      JSON.stringify([
        {
          ...target.confirmation,
          evidence:
            'Confirmed this original child check and all descendants stopped using the host process inventory.',
        },
      ]),
    );
    const command = () =>
      nativeDoctorCommand(
        ['change', '--repair', '--confirmed', '--stopped-actions', proofFile],
        paths.projectRoot,
      );
    const originalWrite = atomicFile.atomicWriteJson;
    const failApplied = vi
      .spyOn(atomicFile, 'atomicWriteJson')
      .mockImplementation(async (file, value, settings) => {
        if (
          (value as { schema?: string; applied?: boolean }).schema ===
            'comet.native.check-stop-evidence.v1' &&
          (value as { applied?: boolean }).applied
        )
          throw new Error('applied write failed');
        return originalWrite(file, value, settings);
      });
    await expect(command()).rejects.toThrow('applied write failed');
    failApplied.mockRestore();
    const interrupted = (await readNativeSupervisorState(paths, 'change'))!;
    expect(interrupted.stateVersion).toBe(preserved.stateVersion + 1);
    expect(interrupted.children[0].task!.checkExecution).toMatchObject({
      status: 'interrupted',
      operationId: execution.operationId,
      activeProcess: null,
      checkStates: [{ id: 'slow', status: 'interrupted', executionCount: 1 }],
    });
    expect(interrupted.children[1].task!.checkExecution).toEqual(
      preserved.children[1].task!.checkExecution,
    );
    await expect(command()).resolves.toMatchObject({
      exitCode: 65,
      data: {
        healthy: false,
        repaired: false,
        stoppedChecks: { alreadyApplied: true },
        findings: [{ code: 'supervisor-check-execution-stuck', child: 'auxiliary' }],
      },
    });
    await expect(command()).resolves.toMatchObject({
      exitCode: 65,
      data: { healthy: false, repaired: false },
    });
    expect(await readNativeSupervisorState(paths, 'change')).toEqual(interrupted);
    expect(execute).toHaveBeenCalledTimes(2);
  });

  it('does not start another check while the registered process outlives its recorded owner', async () => {
    const { paths, marker, release, options } = await setup();
    const running = executeNativeSupervisorChecks(options);
    try {
      let registered = false;
      for (let index = 0; index < 100; index += 1) {
        const state = await readNativeSupervisorState(paths, 'change');
        if (state!.children[0].task!.checkExecution?.activeProcess?.status === 'running') {
          registered = true;
          break;
        }
        await delay(50);
      }
      expect(registered).toBe(true);
      const stoppedPid = Number(
        execFileSync(process.execPath, ['-p', 'process.pid'], { encoding: 'utf8' }).trim(),
      );
      expect(() => process.kill(stoppedPid, 0)).toThrow();
      await withNativeMutationLock(paths, 'simulate exited Supervisor owner', async () => {
        const state = await readNativeSupervisorState(paths, 'change');
        state!.children[0].task!.checkExecution!.ownerPid = stoppedPid;
        await writeNativeSupervisorState(paths, state!);
      });
      const resumed = await executeNativeSupervisorChecks(options);
      expect(resumed.status).toBe('running');
      expect((await fs.readFile(marker, 'utf8')).trim().split(/\r?\n/u)).toHaveLength(1);
    } finally {
      await fs.writeFile(release, 'done');
      await running;
    }
    const completed = await executeNativeSupervisorChecks(options);
    expect(completed.status).toBe('completed');
    // A stopped owner and a finished child provide a safe boundary for a fresh attempt.
    await withNativeMutationLock(paths, 'simulate lost completion write', async () => {
      const state = await readNativeSupervisorState(paths, 'change');
      state!.children[0].task!.checkExecution!.status = 'running';
      await writeNativeSupervisorState(paths, state!);
    });
    const recovered = await executeNativeSupervisorChecks(options);
    expect(recovered.status).toBe('completed');
    expect(recovered.operationId).toBe(completed.operationId);
  }, 60000);

  it('reconciles a complete check receipt even when the former owner process is alive', async () => {
    const { paths, marker, release, options } = await setup();
    await fs.writeFile(release, 'done');
    const completed = await executeNativeSupervisorChecks(options);
    expect(completed.status).toBe('completed');
    await withNativeMutationLock(paths, 'simulate lost completion status', async () => {
      const state = await readNativeSupervisorState(paths, 'change');
      state!.children[0].task!.checkExecution!.status = 'running';
      await writeNativeSupervisorState(paths, state!);
    });

    const recovered = await executeNativeSupervisorChecks(options);
    expect(recovered.status).toBe('completed');
    expect(recovered.operationId).toBe(completed.operationId);
    expect((await fs.readFile(marker, 'utf8')).trim().split(/\r?\n/u)).toHaveLength(1);
  }, 60000);

  it('does not reuse a completed receipt for changed inputs after the former owner exits', async () => {
    const { paths, marker, release, options } = await setup();
    await fs.writeFile(release, 'done');
    const completed = await executeNativeSupervisorChecks(options);
    expect(completed.status).toBe('completed');
    const stoppedPid = Number(
      execFileSync(process.execPath, ['-p', 'process.pid'], { encoding: 'utf8' }).trim(),
    );
    await withNativeMutationLock(
      paths,
      'simulate lost completion status and exited owner',
      async () => {
        const state = await readNativeSupervisorState(paths, 'change');
        const execution = state!.children[0].task!.checkExecution!;
        execution.status = 'running';
        execution.ownerPid = stoppedPid;
        await writeNativeSupervisorState(paths, state!);
      },
    );

    const changedMarker = path.join(path.dirname(marker), 'changed-starts.txt');
    const changed = await executeNativeSupervisorChecks({
      ...options,
      plans: [
        { ...options.plans[0], argv: ['-e', options.plans[0].argv[1], changedMarker, release] },
      ],
    });
    expect(changed.status).toBe('completed');
    expect(changed.operationId).not.toBe(completed.operationId);
    expect((await fs.readFile(changedMarker, 'utf8')).trim().split(/\r?\n/u)).toHaveLength(1);
  }, 60000);

  it('does not replay an unregistered process and provides a candidate-preserving recovery route', async () => {
    const { paths, release, options } = await setup();
    await fs.writeFile(release, 'done');
    await executeNativeSupervisorChecks(options);
    const stoppedPid = Number(
      execFileSync(process.execPath, ['-p', 'process.pid'], { encoding: 'utf8' }).trim(),
    );
    expect(() => process.kill(stoppedPid, 0)).toThrow();
    await withNativeMutationLock(
      paths,
      'simulate interruption during process registration',
      async () => {
        const state = await readNativeSupervisorState(paths, 'change');
        const execution = state!.children[0].task!.checkExecution!;
        execution.status = 'running';
        execution.ownerPid = stoppedPid;
        execution.activeProcess = { status: 'starting', checkId: 'slow' };
        await writeNativeSupervisorState(paths, state!);
      },
    );
    await expect(executeNativeSupervisorChecks(options)).rejects.toThrow('supervisor-cancel');
    const before = await readNativeSupervisorState(paths, 'change');
    const cancelled = await applyNativeRunnerInput({
      paths,
      name: 'change',
      maxVerifyFailures: 5,
      input: {
        kind: 'supervisor-cancel',
        child: 'core',
        runId: options.runId,
        reason: 'Confirmed original check exited',
      },
    });
    expect(cancelled.supervisorState!.children[0].candidateCommit).toBe(
      before!.children[0].candidateCommit,
    );
    expect(cancelled.supervisorState!.children[0].status).toBe('needs-reverify');
  }, 60000);

  it('requires explicit retry for interrupted checks and preserves passed checks', async () => {
    const { paths, release, options } = await setup();
    const plans = [
      {
        ...options.plans[0],
        id: 'passed',
        name: 'Passed check',
        argv: ['-e', 'process.exit(0)'],
      },
      {
        ...options.plans[0],
        id: 'interrupted',
        name: 'Interrupted check',
        timeoutMs: 5000,
        argv: [
          '-e',
          "const fs=require('node:fs');const f=process.argv[1];if(fs.existsSync(f))process.exit(0);setInterval(()=>{},25)",
          release,
        ],
      },
    ];
    await expect(executeNativeSupervisorChecks({ ...options, plans })).rejects.toThrow(
      'was interrupted',
    );
    const interrupted = (await readNativeSupervisorState(paths, 'change'))!;
    const firstExecution = interrupted.children[0].task!.checkExecution!;
    expect(firstExecution.status).toBe('interrupted');
    expect(firstExecution.checkStates).toMatchObject([
      { id: 'passed', status: 'passed', executionCount: 1 },
      { id: 'interrupted', status: 'interrupted', executionCount: 1 },
    ]);

    const awaitingRetry = await executeNativeSupervisorChecks({ ...options, plans });
    expect(awaitingRetry).toMatchObject({
      status: 'interrupted',
      operationId: firstExecution.operationId,
    });
    await fs.writeFile(release, 'retry');
    const completed = await executeNativeSupervisorChecks({
      ...options,
      plans,
      retryCheckIds: ['interrupted'],
    });
    expect(completed.status).toBe('completed');
    const finalState = (await readNativeSupervisorState(paths, 'change'))!;
    expect(finalState.children[0].task!.checkExecution!.checkStates).toMatchObject([
      { id: 'passed', status: 'passed', executionCount: 1 },
      { id: 'interrupted', status: 'passed', executionCount: 2 },
    ]);
  }, 60000);
});

