  vi.restoreAllMocks();
  for (const root of roots.splice(0)) await fs.rm(root, { recursive: true, force: true });
});
const plan = (id: string, code = 'process.exit(0)', args: string[] = []) => ({
  id,
  name: id,
  executable: process.execPath,
  argv: ['-e', code, ...args],
  cwdRef: '.',
  timeoutMs: 20000,
  repeatable: true,
});

async function verifiedSupervisor() {
  const root = await fs.mkdtemp(path.join(os.tmpdir(), 'comet-integration-execution-'));
  roots.push(root);
  const git = (cwd: string, ...args: string[]) =>
    execFileSync('git', args, { cwd, encoding: 'utf8', stdio: 'pipe' }).trim();
  git(root, 'init', '-b', 'main');
  git(root, 'config', 'user.email', 'native@example.test');
  git(root, 'config', 'user.name', 'Native Test');
  await writeProjectConfig(root, defaultProjectConfig('docs', 'en'));
  await fs.writeFile(
    path.join(root, '.gitignore'),
    '.comet/runtime/\n.comet/current-change.json\n.worktrees/\n',
  );
  git(root, 'add', '.');
  git(root, 'commit', '-m', 'seed');
  const paths = await nativeProjectPaths(root, 'docs');
  await ensureNativeDirectories(paths);
  await createNativePortableChange({
    paths,
    name: 'parent',
    language: 'en',
    workspaceBinding: { isolation: 'current', changeBranch: 'main', targetBranch: 'main' },
  });
  const changeDir = nativePortableChangeDir(paths, 'parent');
  await fs.writeFile(
    path.join(changeDir, 'brief.md'),
    '# Acceptance examples\n- The behavior works.\n',
  );
  await fs.writeFile(
    path.join(changeDir, 'children.yaml'),
    'schema: comet.native.children.v2\nchildren:\n  - name: core\n    summary: Core behavior.\n    depends_on: []\n',
  );
  await confirmNativePortableShape({ paths, name: 'parent' });
  const dispatched = await dispatchNativeSupervisorReadyTasks({
    paths,
    parent: 'parent',
    maxParallel: 1,
  });
  const builder = dispatched.tasks[0];
  await fs.writeFile(path.join(builder.projectRoot, 'feature.txt'), 'implemented');
  git(builder.projectRoot, 'add', 'feature.txt');
  git(builder.projectRoot, 'commit', '-m', 'implement');
  const result = await applyNativeRunnerInput({
    paths,
    name: 'parent',
    maxVerifyFailures: 5,
    input: {
      kind: 'supervisor-builder-result',
      child: 'core',
      runId: builder.runId,
      candidateCommit: git(builder.projectRoot, 'rev-parse', 'HEAD'),
    },
  });
  const verifier = result.supervisorTask!;
  const checked = await executeNativeSupervisorChecks({
    paths,
    parent: 'parent',
    child: 'core',
    runId: verifier.runId,
    plans: [plan('child')],
    materials: [],
  });
  await applyNativeRunnerInput({
    paths,
    name: 'parent',
    maxVerifyFailures: 5,
    input: {
      kind: 'supervisor-verifier-result',
      child: 'core',
      runId: verifier.runId,
      verdict: 'pass',
      evidence: {
        summary: 'Verified.',
        checks: ['child'],
        receiptRef: checked.receiptRef,
        acceptance: [{ id: 'child:core', result: 'passed', reason: 'Checked.' }],
      },
    },
  });
  return { root, paths, state: (await readNativeSupervisorState(paths, 'parent'))! };
}

describe('Supervisor integration check execution', () => {
  it('preserves unconfirmed process termination and blocks owner-dead recovery', async () => {
    const { paths, state } = await verifiedSupervisor();
    const failure = new checkExecutor.NativeCheckTerminationUnconfirmedError();
    const originalExecute = checkExecutor.executeNativeCheck;
    const execute = vi
      .spyOn(checkExecutor, 'executeNativeCheck')
      .mockImplementation(async (options) => {
        if (options.plan.id === 'passed') return originalExecute(options);
        await options.onSpawn?.({
          instanceId: 'original-check-instance',
          signal: new AbortController().signal,
        });
        throw failure;
      });
    const options = {
      paths,
      state,
      name: 'core',
      checks: [],
      checkPlans: [plan('passed'), plan('pending')],
    };
    await expect(integrateNativeSupervisorChildWorkspace(options)).rejects.toBe(failure);
    const preserved = (await readNativeSupervisorState(paths, 'parent'))!;
    const execution = preserved.integration.checkExecution!;
    expect(execution).toMatchObject({
      status: 'running',
      activeProcess: {
        status: 'running',
        checkId: 'pending',
        instanceId: 'original-check-instance',
      },
      checkStates: [
        { id: 'passed', status: 'passed', executionCount: 1 },
        { id: 'pending', status: 'running', executionCount: 1 },
      ],
    });
    await expect(
      integrateNativeSupervisorChildWorkspace({
        ...options,
        state: preserved,
        retryCheckIds: ['pending'],
      }),
    ).rejects.toThrow('are running');

    execution.ownerPid = 2147483001;
    await writeNativeSupervisorState(paths, preserved);
    await expect(
      integrateNativeSupervisorChildWorkspace({ ...options, state: preserved }),
    ).rejects.toThrow('are running');
    expect((await readNativeSupervisorState(paths, 'parent'))!.integration.checkExecution).toEqual(
      execution,
    );
    expect(execute).toHaveBeenCalledTimes(2);
    const target = (await inspectNativeCheckStopEvidenceTargets(paths, 'parent')).find(
      ({ kind }) => kind === 'supervisor-integration-checks',
    )!;
    expect(target.canConfirm).toBe(true);
    const confirmation = {
      ...target.confirmation,
      evidence:
        'Confirmed the integration check and all descendants stopped using the host process inventory.',
    };
    const recover = (confirmations: unknown = [confirmation]) =>
      recoverNativeChecksWithStopEvidence({ paths, name: 'parent', confirmations });
    await expect(recover([{ ...confirmation, executionHash: '0'.repeat(64) }])).rejects.toThrow(
      '快照已变化',
    );
    expect(await readNativeSupervisorState(paths, 'parent')).toEqual(preserved);
    const originalWrite = atomicFile.atomicWriteJson;
    const failApplied = vi
      .spyOn(atomicFile, 'atomicWriteJson')
      .mockImplementation(async (file, value, settings) => {
        if (
          (value as { schema?: string; applied?: boolean }).schema ===
            'comet.native.check-stop-evidence.v1' &&
          (value as { applied?: boolean }).applied
        )
          throw new Error('applied write failed');
        return originalWrite(file, value, settings);
      });
    await expect(recover()).rejects.toThrow('applied write failed');
    failApplied.mockRestore();
    const recovered = (await readNativeSupervisorState(paths, 'parent'))!;
    expect(recovered.stateVersion).toBe(preserved.stateVersion + 1);
    expect(recovered.integration.checkExecution).toMatchObject({
      status: 'interrupted',
      operationId: execution.operationId,
      activeProcess: null,
      checkStates: [
        { id: 'passed', status: 'passed', executionCount: 1 },
        { id: 'pending', status: 'interrupted', executionCount: 1 },
      ],
    });
    expect(recovered.integration.checkExecution!.checkStates![0]).toEqual(
      execution.checkStates![0],
    );
    await expect(recover()).resolves.toMatchObject({ alreadyApplied: true });
    await expect(recover()).resolves.toMatchObject({ alreadyApplied: true });
    expect(await readNativeSupervisorState(paths, 'parent')).toEqual(recovered);
    expect(execute).toHaveBeenCalledTimes(2);
  });

  it('reserves the integration worktree before running checks with competing plans', async () => {
    const { root, paths, state } = await verifiedSupervisor();
    const marker = path.join(resolveWorkspaceRuntimeRootSync(root), 'integration-started');
    const release = path.join(resolveWorkspaceRuntimeRootSync(root), 'integration-release');
    const first = integrateNativeSupervisorChildWorkspace({
      paths,
      state,
      name: 'core',
      checks: [],
      checkPlans: [
        plan(
          'first',
          "const fs=require('node:fs');fs.writeFileSync(process.argv[1],'started');const timer=setInterval(()=>{if(fs.existsSync(process.argv[2])){clearInterval(timer);process.exit(0)}},20)",
          [marker, release],
        ),
      ],
    });
    // Attach a handler while the competing request is inspected.
    const settled = first.then(
      (value) => ({ value }),
      (error) => ({ error }),
    );
    try {
      await expect
        .poll(
          async () =>
            fs.access(marker).then(
              () => true,
              () => false,
            ),
          { timeout: 10000 },
        )
        .toBe(true);
      await expect(
        integrateNativeSupervisorChildWorkspace({
          paths,
          state,
          name: 'core',
          checks: [],
          checkPlans: [plan('different')],
        }),
      ).rejects.toThrow(/running|state changed/);
      const latest = (await readNativeSupervisorState(paths, 'parent'))!;
      await expect(
        integrateNativeSupervisorChildWorkspace({
          paths,
          state: latest,
          name: 'core',
          checks: [],
          checkPlans: [plan('different')],
        }),
      ).rejects.toThrow(/running/);
      await expect
        .poll(
          async () =>
            (await readNativeSupervisorState(paths, 'parent'))?.integration.checkExecution
              ?.activeProcess?.status,
          { timeout: 10000 },
        )
        .toBe('running');
      const orphaned = (await readNativeSupervisorState(paths, 'parent'))!;
      // A recovered overlay may refer to an exited owner while its real check is alive.
      orphaned.integration.checkExecution!.ownerIdentity = 'previous-owner-instance';
      await fs.writeFile(nativeSupervisorStateFile(paths, 'parent'), JSON.stringify(orphaned));
      await expect(
        integrateNativeSupervisorChildWorkspace({
          paths,
          state: orphaned,
          name: 'core',
          checks: [],
          checkPlans: [plan('orphan-retry')],
        }),
      ).rejects.toThrow('are running');
    } finally {
      await fs.writeFile(release, 'release');
      await settled;
    }
    expect(await settled).toMatchObject({
      value: {
        children: [{ status: 'integrated', checks: [{ name: 'first', status: 'passed' }] }],
      },
    });
  }, 120000);

  it('preserves a failed integration receipt and requires a changed plan before retry', async () => {
    const { paths, state } = await verifiedSupervisor();
    await expect(
      integrateNativeSupervisorChildWorkspace({
        paths,
        state,
        name: 'core',
        checks: [],
        checkPlans: [plan('fails', 'process.exit(1)')],
      }),
    ).rejects.toThrow('did not pass');
    const failed = (await readNativeSupervisorState(paths, 'parent'))!;
    expect(failed.children[0].status).toBe('verified');
    expect(failed.integration.checkExecution).toMatchObject({
      status: 'interrupted',
      activeProcess: null,
      receiptRef: expect.stringMatching(/^runtime\/checks\/[a-f0-9-]+\.json$/u),
      checks: [{ name: 'fails', status: 'failed' }],
    });
    await expect(
      integrateNativeSupervisorChildWorkspace({
        paths,
        state: failed,
        name: 'core',
        checks: [],
        checkPlans: [plan('fails', 'process.exit(1)')],
      }),
    ).rejects.toThrow('already failed on the identical plan');
    expect((await readNativeSupervisorState(paths, 'parent'))!.integration.checkExecution).toEqual(
      failed.integration.checkExecution,
    );
    const completed = await integrateNativeSupervisorChildWorkspace({
      paths,
      state: failed,
      name: 'core',
      checks: [],
      checkPlans: [plan('retry')],
    });
    expect(completed.children[0]).toMatchObject({
      status: 'integrated',
      checks: [{ name: 'retry', status: 'passed' }],
    });
    expect(completed.integration.checkExecution).toMatchObject({
      status: 'completed',
      activeProcess: null,
    });
    expect(completed.integration.checkExecution!.operationId).not.toBe(
      failed.integration.checkExecution!.operationId,
    );
  }, 120000);

  it('exposes only interrupted integration checks as an explicit retry action', async () => {
    const { paths, state } = await verifiedSupervisor();
    await expect(
      integrateNativeSupervisorChildWorkspace({
        paths,
        state,
        name: 'core',
        checks: [],
        checkPlans: [{ ...plan('interrupted', 'setInterval(() => {}, 25)', []), timeoutMs: 5000 }],
      }),
    ).rejects.toThrow('was interrupted');

    const current = (await readNativeSupervisorState(paths, 'parent'))!;
    const portable = await readNativePortableChange(paths, 'parent');
    const children = await inspectNativeChildren({ paths, state: portable });
    const continuation = nativePortableContinuation(portable, children, {
      supervisorIntegrationRetryIds: current.integration.checkExecution?.checkStates
        ?.filter(({ status }) => status === 'interrupted')
        .map(({ id }) => id),
    });
    const template = continuation.inputOptions.find(
      ({ template }) =>
        !Array.isArray(template) && (template as { kind?: string }).kind === 'supervisor-integrate',
    )?.template as { retry_check_ids?: string[] } | undefined;
    expect(template?.retry_check_ids).toEqual(['interrupted']);
  }, 120000);
});

