      },
    });
    state = await dispatchNativePortableVerifier({
      paths,
      name: state.name,
      checks: executed.checks,
      verifierExecutionId: 'late-verifier-2',
    });
    const before = state;

    await expect(
      submitNativePortableVerifierResult({
        paths,
        name: state.name,
        checks: executed.checks,
        maxVerifyFailures: 5,
        envelope: runner.envelopeVerifierResponse({
          candidateId: 'late-candidate',
